// Zusammenfassung Personalentwicklung – eigene Formulierungen und eigene Schaubilder
(window.TEXTBAND=window.TEXTBAND||{}).PE={
 title:'Personalentwicklung',
 src:'Zusammenfassung nach dem Lehrgangs-Textband',
 intro:'Personalentwicklung heißt: Qualifikationslücken erkennen, Potenziale sichten, passende Maßnahmen auswählen und deren Wirkung im Arbeitsalltag absichern. In der Prüfung zählt die Meister-Sicht – strukturiert vorgehen (Soll-Ist, SMART, Regelkreis), Maßnahmen begründen, Personalbedarf rechnen können, Transfer sichern sowie Betriebsrat und Datenschutz mitdenken.',
 ch:[
  {t:'Personalplanung und Ermittlung des PE-Bedarfs',h:'1.1 Methoden der Ermittlung des Personalentwicklungsbedarfs',pg:1,pdf:3,abb:[['Abb. 1.1 Teilbereiche der Personalplanung',2]],b:[
    {p:'Der Meister soll die ihm übertragenen Ziele mit Budget, Maschinen und Personal erreichen. Personalplanung schafft dafür die Grundlage: die passenden Mitarbeitenden in der nötigen Zahl, zur richtigen Zeit, am richtigen Ort und zu vertretbaren Kosten. Geplant wird dabei immer zweifach – Köpfe (quantitativ) und Können (qualitativ).'},
    {tab:[['Begriff','Bedeutung','Beispiel Metallbetrieb'],['quantitativ','zählen, messen: Anzahl Personen bzw. FTE (1,0 FTE = eine Vollzeitstelle)','Schweißerei braucht ab März 6,5 FTE statt 5,0'],['qualitativ','beschreibend: Fähigkeiten, Fertigkeiten, Kompetenzen','zwei davon müssen WIG-Aluminium schweißen können']]},
    {svg:{w:520,h:290,body:'<g class="sk-t" text-anchor="middle"><rect x="185" y="125" width="150" height="50" class="sk-body"/><text x="260" y="146" class="sk-t acc">Personal-</text><text x="260" y="164" class="sk-t acc">planung</text><rect x="10" y="20" width="150" height="44" class="sk-body"/><text x="85" y="38" class="sk-t acc">Personalbedarf</text><text x="85" y="56">Wie viele, welche?</text><rect x="360" y="20" width="150" height="44" class="sk-body"/><text x="435" y="38" class="sk-t acc">Personalbestand</text><text x="435" y="56">Wer ist da, wer geht?</text><rect x="10" y="128" width="150" height="44" class="sk-body"/><text x="85" y="146" class="sk-t acc">Anpassung</text><text x="85" y="164">Über-/Unterdeckung</text><rect x="360" y="128" width="150" height="44" class="sk-body"/><text x="435" y="146" class="sk-t acc">Einsatz</text><text x="435" y="164">Wer, wann, wo?</text><rect x="10" y="236" width="150" height="44" class="sk-body"/><text x="85" y="254" class="sk-t acc">Entwicklung</text><text x="85" y="272">Welche Qualifizierung?</text><rect x="360" y="236" width="150" height="44" class="sk-body"/><text x="435" y="254" class="sk-t acc">Personalkosten</text><text x="435" y="272">Was kostet es?</text><path d="M185,135 L160,60 M335,135 L360,60 M185,150 H160 M335,150 H360 M185,165 L160,240 M335,165 L360,240" class="sk-l"/></g>',cap:'Teilplanungen der Personalplanung – jede beantwortet eine eigene Leitfrage'}},
    {tab:[['Teilplanung','Leitfrage','Zusammenhang zur PE'],['Personalbedarfsplanung','Wie viele und welche Mitarbeitenden brauchen wir?','beeinflusst Nachwuchsprogramme'],['Personalbestandsplanung','Wer ist da, wer scheidet aus (Rente, Fluktuation)?','wirkt auf die Nachfolgeplanung'],['Personalanpassungsplanung','Wie decken wir Über- oder Unterdeckung?','Umsetzung, Qualifizierung, Einstellung'],['Personaleinsatzplanung','Wer arbeitet wann an welchem Platz?','Quali-Matrix, Einsatzflexibilität'],['Personalentwicklungsplanung','Welche Fort- und Weiterbildung braucht es?','Kern dieses Fachs'],['Personalkostenplanung','Welche Kosten entstehen?','Bildungsbudget, Freistellung']]},
    {p:'Personalentwicklungsplanung fasst alle Planungen zu Fort- und Weiterbildung zusammen. Methodisch geht es um zwei Fragen:'},
    {ol:['Soll-Ist-Abgleich: Anforderungen der Tätigkeit (Kompetenzen, Qualifizierungen, Erfahrung) gegen den Ist-Stand der Person – z. B. über Assessment-Center oder Mitarbeiterbeurteilung.','Potenzialsicht: Welche Talente und Anlagen haben Beschäftigte, die sich mit wenig Aufwand in Leistung übersetzen lassen – z. B. über Development-Center, Entwicklungsgespräch, Potenzialeinschätzung.']},
    {svg:{w:520,h:200,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="20" width="170" height="50" class="sk-body"/><text x="95" y="40" class="sk-t acc">Soll</text><text x="95" y="58">Anforderungsprofil</text><rect x="10" y="130" width="170" height="50" class="sk-body"/><text x="95" y="150" class="sk-t acc">Ist</text><text x="95" y="168">Fähigkeiten der Person</text><rect x="215" y="75" width="110" height="50" class="sk-body"/><text x="270" y="96">Soll-Ist-</text><text x="270" y="114">Abgleich</text><rect x="360" y="20" width="150" height="50" class="sk-body"/><text x="435" y="40">Lücke =</text><text x="435" y="58" class="sk-t acc">PE-Bedarf</text><rect x="360" y="130" width="150" height="50" class="sk-body"/><text x="435" y="150">Maßnahme</text><text x="435" y="168">planen + prüfen</text><path d="M180,45 L213,88" class="sk-l" marker-end="url(#ar)"/><path d="M180,155 L213,112" class="sk-l" marker-end="url(#ar)"/><path d="M325,100 L358,52" class="sk-l" marker-end="url(#ar)"/><path d="M435,70 L435,128" class="sk-f" marker-end="url(#ar)"/></g>',cap:'Vom Soll-Ist-Abgleich zum Qualifizierungsbedarf'}},
    {ul:['Erhebungswege: schriftliche Mitarbeiterbefragung, mündliche Befragung (Interview, Mitarbeitergespräch), Gruppenerhebung, Beobachtung in realen Situationen (on the job), Beobachtung in künstlichen Situationen (AC), Ableitung aus Dokumenten (Strategiepapiere, Stellenbeschreibungen).','Digital gestützt: Online-Befragungen sind schneller, Daten werden nur einmal erfasst (weniger Fehler, weniger Kosten), Zwischenergebnisse sind sofort sichtbar.','Besprechungen und Gespräche laufen zunehmend über Kollaborationssoftware (z. B. Teams, Zoom) – spart Reisen und beschleunigt Klärungen, verlangt aber bewusste Gesprächsführung.','Auch AC und DC lassen sich teilweise digital durchführen.','Grenze der Digitalisierung: verdichtete Daten muss ein Mensch mit Sachverstand sichten und entscheiden – auch abweichend von algorithmischen Empfehlungen.','Datenschutz: DSGVO und BDSG gelten für alle Kompetenz- und Beurteilungsdaten (Zweckbindung, Zugriffsrechte, Löschfristen).','Überschneidung mit Personalführung: Bestandsplanung wirkt auf Nachfolge, Bedarfsplanung auf Nachwuchsprogramme und Qualifizierungsbedarf.']},
    {bsp:{t:'Beispiel: Bedarf in der Instandhaltung ermitteln',b:['Anlass: Im nächsten Jahr kommen zwei Roboterzellen mit neuer Steuerung; ein erfahrener Elektriker geht in Rente.','Quantitativ: Wartungsaufwand steigt um ca. 600 h/Jahr ≈ 0,4 FTE; plus Ersatz für den Rentner = 1,4 FTE Bedarf.','Qualitativ: Anforderungsprofil „Roboter-Instandhaltung“ aufstellen (Steuerung, Sicherheitstechnik, Fehlersuche).','Ist-Stand: Jahresgespräche und Quali-Matrix zeigen: zwei Mechatroniker haben Grundkenntnisse, niemand die neue Steuerung.','Ergebnis: Herstellerschulung für zwei Mechatroniker, Einarbeitung eines Nachfolgers beim Rentner (6 Monate Überlappung), 0,4 FTE über Ausschreibung.']}},
    {merke:'PE-Bedarf = Differenz zwischen Anforderung (Soll) und vorhandener Kompetenz (Ist) – heute und absehbar morgen. Erst messen, dann Maßnahmen planen.'}
  ]},
  {t:'Personaleinsatzplanung mit der Quali-Matrix',h:'1.1 Methoden der Ermittlung des Personalentwicklungsbedarfs',pg:3,pdf:5,abb:[['Beispiel: Übersicht zur Mitarbeitereinsatzflexibilität',3]],b:[
    {p:'Die Personaleinsatzplanung hängt von Schichtmodellen und Verfügbarkeit ab. Ziel ist, die Beschäftigten nach ihren räumlichen und zeitlichen Möglichkeiten und ihren Kompetenzen möglichst gut einzusetzen. Das klassische Werkzeug dafür ist die Polyvalenz- und Polykompetenzmatrix (Quali-Matrix).'},
    {tab:[['Begriff','Bedeutung'],['Polyvalenz','eine Person beherrscht mehrere Arbeitsplätze'],['Polykompetenz','die unterschiedlichen Kompetenzen, die ein Arbeitsplatz verlangt'],['Einsatzflexibilität','wie vielseitig das Team geplante und ungeplante Ausfälle ausgleichen kann'],['Kopfmonopol','nur eine Person verfügt über ein bestimmtes Know-how']]},
    {svg:{w:520,h:240,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="20" width="500" height="150" class="sk-l"/><path d="M150,20 V170 M210,20 V170 M270,20 V170 M330,20 V170 M390,20 V170 M450,20 V170 M10,50 H510 M10,80 H510 M10,110 H510 M10,140 H510" class="sk-l"/><text x="80" y="40" class="sk-t acc">Tätigkeit</text><text x="180" y="40">MA A</text><text x="240" y="40">MA B</text><text x="300" y="40">MA C</text><text x="360" y="40">MA D</text><text x="420" y="40" class="sk-t acc">Soll</text><text x="480" y="40" class="sk-t acc">Ist</text><text x="20" y="70" text-anchor="start">Drehen</text><text x="180" y="70">3</text><text x="240" y="70">4</text><text x="300" y="70">2</text><text x="360" y="70">–</text><text x="420" y="70">3</text><text x="480" y="70" class="sk-t acc">2 !</text><text x="20" y="100" text-anchor="start">CNC-Fräsen</text><text x="180" y="100">4</text><text x="240" y="100">1</text><text x="300" y="100">3</text><text x="360" y="100">3</text><text x="420" y="100">3</text><text x="480" y="100">3</text><text x="20" y="130" text-anchor="start">MAG-Schweißen</text><text x="180" y="130">–</text><text x="240" y="130" class="sk-t acc">3</text><text x="300" y="130">–</text><text x="360" y="130">2</text><text x="420" y="130">2</text><text x="480" y="130" class="sk-t acc">1 !</text><text x="20" y="160" text-anchor="start">Messen/Prüfen</text><text x="180" y="160">3</text><text x="240" y="160">3</text><text x="300" y="160">3</text><text x="360" y="160">1</text><text x="420" y="160">2</text><text x="480" y="160">3</text><text x="10" y="198" text-anchor="start">1 = in Einarbeitung · 2 = beherrscht · 3 = in Qualität und Zeit</text><text x="10" y="218" text-anchor="start">4 = kann andere einarbeiten · Ist = Anzahl mit Stufe 3 oder 4</text><text x="10" y="236" text-anchor="start" class="sk-t acc">MAG-Schweißen: nur MA B sicher → Kopfmonopol</text></g>',cap:'Eigenes Beispiel einer Quali-Matrix aus der Fertigung'}},
    {ul:['Typische Stufen: in Einarbeitung – beherrscht den Arbeitsgang – beherrscht ihn in Qualität und Zeit – kann andere einarbeiten. Je Tätigkeit wird ein Soll (wie viele müssen es können) festgelegt.','Spaltenweise (je Person): Generalist oder Spezialist? Aktueller Kompetenzstand? Lernthemen und Lernbedarfe? Weitere Einsatzmöglichkeiten?','Zeilenweise (je Tätigkeit): Wie stabil ist der Prozess? Mögliche Ursache bei Qualitätsmängeln? Wo liegt Schulungsbedarf? Wo gibt es Kopfmonopole?','Vorteile flexiblen Einsatzes: Ausfälle (Urlaub, Krankheit, Mehrschicht) abfangen, einseitige Belastung vermeiden, breiteres Fähigkeitsspektrum aufbauen.','Form: Papier, meist Excel, teils Funktion der Personalsoftware. Den Ist-Stand und den Lernfortschritt dokumentiert aber weiter ein Mensch.','Die Quali-Matrix dient in erster Linie der qualitativen Personalplanung, konkret der Einsatz- und Entwicklungsplanung auf Basis der Qualifikation.']},
    {fx:{n:'Abdeckungsgrad einer Tätigkeit',tex:'\\text{AG} = \\frac{n_\\text{QZ}}{n_\\text{Soll}} \\cdot 100\\,\\%',leg:[['\\text{AG}','Abdeckungsgrad in %'],['n_\\text{QZ}','Personen, die die Tätigkeit mindestens in Qualität und Zeit beherrschen'],['n_\\text{Soll}','geforderte Anzahl Personen (Soll)']],e:'Unter 100 % → Vertretungsrisiko; genau eine Person → Kopfmonopol.'}},
    {bsp:{t:'Beispiel: Kopfmonopol beim Biegezentrum',b:['Auswertung der Matrix: Das neue CNC-Biegezentrum beherrscht nur Herr K. in Qualität und Zeit; Soll sind 3 Personen für 2-Schicht-Betrieb.','Abdeckungsgrad: 1 ÷ 3 × 100 % ≈ 33 % – hohes Ausfallrisiko bei Urlaub oder Krankheit.','Maßnahme: Herr K. wird als Pate benannt und arbeitet in den nächsten 8 Wochen zwei Kollegen ein (je 2 Schichten/Woche Tandem).','Kontrolle: Matrix monatlich fortschreiben; Ziel nach 3 Monaten: 3 von 3 = 100 %.','Nebeneffekt: Herr K. erhält Anerkennung als Ausbilder; das Wissen wird gesichert.']}},
    {falle:'Die Quali-Matrix ist ein Planungsinstrument, keine Leistungsbeurteilung. Der Betriebsrat ist bei der Personalplanung zu unterrichten (§ 92 BetrVG); wird sie elektronisch geführt und kann Leistung oder Verhalten auswerten, gilt Mitbestimmung nach § 87 Abs. 1 Nr. 6 BetrVG. Beurteilungsgrundsätze unterliegen § 94 BetrVG.'}
  ]},
  {t:'Quantitativen Personalbedarf berechnen',h:'Berufstypische Aufgaben zu Kapitel 1 (Personalbedarf)',pg:8,pdf:10,abb:[['Lösungshinweise zu Kapitel 1',66]],b:[
    {p:'Typische Situationsaufgabe: Ein Auftrag mit Stückzahl, Vorgabezeit und Termin. Gesucht sind die Zahl der Mitarbeitenden, die nötige Mehrarbeit oder der nötige Zeitgrad – und Maßnahmen bei Ausfällen.'},
    {svg:{w:520,h:270,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="20" width="170" height="50" class="sk-body"/><text x="95" y="40" class="sk-t acc">Kapazitätsbedarf</text><text x="95" y="58">Stück × Zeit je Stück</text><rect x="10" y="110" width="170" height="50" class="sk-body"/><text x="95" y="130" class="sk-t acc">Kapazität je MA</text><text x="95" y="148">Tage × h × Quote</text><rect x="215" y="65" width="130" height="50" class="sk-body"/><text x="280" y="85" class="sk-t acc">Personalbedarf</text><text x="280" y="103">Bedarf ÷ je MA</text><rect x="380" y="65" width="130" height="50" class="sk-body"/><text x="445" y="85" class="sk-t acc">Aufrunden</text><text x="445" y="103">ganze Personen</text><path d="M180,45 L213,80" class="sk-l" marker-end="url(#ar)"/><path d="M180,135 L213,100" class="sk-l" marker-end="url(#ar)"/><path d="M345,90 H378" class="sk-l" marker-end="url(#ar)"/><path d="M445,115 V160 H280 V166" class="sk-l" marker-end="url(#ar)"/><polygon points="280,168 360,200 280,232 200,200" class="sk-body"/><text x="280" y="205">genug MA da?</text><rect x="10" y="178" width="160" height="44" class="sk-body"/><text x="90" y="196" class="sk-t acc">ja</text><text x="90" y="214">Einsatz planen</text><rect x="390" y="178" width="120" height="44" class="sk-body"/><text x="450" y="196" class="sk-t acc">nein</text><text x="450" y="214">Lücke schließen</text><path d="M200,200 H172" class="sk-f" marker-end="url(#ar)"/><path d="M360,200 H388" class="sk-f" marker-end="url(#ar)"/><text x="260" y="258">Mehrarbeit, Zeitgrad, Leiharbeit, Umsetzung, Fremdvergabe</text></g>',cap:'Rechenweg zum quantitativen Personalbedarf'}},
    {fx:{n:'Kapazitätsbedarf eines Auftrags',tex:'K_\\text{B} = \\frac{m \\cdot t_\\text{e}}{60}',leg:[['K_\\text{B}','Kapazitätsbedarf in h'],['m','Stückzahl'],['t_\\text{e}','Vorgabezeit je Stück in min'],['60','Umrechnung min → h']],e:'Ist die Vorgabezeit schon in Stunden gegeben, entfällt die Division durch 60.'}},
    {fx:{n:'Verfügbare Kapazität je Mitarbeitendem',tex:'K_\\text{MA} = d \\cdot h \\cdot q_\\text{A}',leg:[['K_\\text{MA}','Kapazität je Mitarbeitendem in h'],['d','Arbeitstage im Planungszeitraum'],['h','Arbeitsstunden je Tag'],['q_\\text{A}','Anwesenheitsquote als Dezimalzahl (96 % = 0,96)']]}},
    {fx:{n:'Personalbedarf (quantitativ)',tex:'P = \\frac{K_\\text{B}}{d \\cdot h \\cdot q_\\text{A}} = \\frac{K_\\text{B}}{K_\\text{MA}}',leg:[['P','Anzahl benötigter Mitarbeitender'],['K_\\text{B}','Kapazitätsbedarf in h'],['d','Arbeitstage'],['h','Stunden je Tag'],['q_\\text{A}','Anwesenheitsquote als Dezimalzahl (96 % = 0,96)']],e:'Immer auf ganze Personen aufrunden.'}},
    {fx:{n:'Kapazitätsbestand',tex:'K_\\text{ist} = P_\\text{ist} \\cdot d \\cdot h \\cdot q_\\text{A}',leg:[['K_\\text{ist}','vorhandene Kapazität in h'],['P_\\text{ist}','verfügbare Mitarbeitende'],['d','Arbeitstage'],['h','Stunden je Tag'],['q_\\text{A}','Anwesenheitsquote als Dezimalzahl (96 % = 0,96)']]}},
    {fx:{n:'Fehlstunden',tex:'\\Delta K = K_\\text{B} - K_\\text{ist}',leg:[['\\Delta K','fehlende Kapazität in h'],['K_\\text{B}','Kapazitätsbedarf in h'],['K_\\text{ist}','Kapazitätsbestand in h']]}},
    {fx:{n:'Mehrarbeit je Mitarbeitendem und Tag',tex:'M = \\frac{\\Delta K}{P_\\text{ist} \\cdot d \\cdot q_\\text{A}}',leg:[['M','Mehrarbeit in h je MA und Tag'],['\\Delta K','Fehlstunden in h'],['P_\\text{ist}','verfügbare Mitarbeitende'],['d','Arbeitstage'],['q_\\text{A}','Anwesenheitsquote als Dezimalzahl (96 % = 0,96)']],e:'Verteilt die Mehrarbeit auf die tatsächlich Anwesenden. ArbZG: max. 10 h/Tag; Betriebsrat § 87 Abs. 1 Nr. 3 BetrVG.'}},
    {fx:{n:'Zeitgrad',tex:'Z = \\frac{t_\\text{Vorgabe}}{t_\\text{Ist}} \\cdot 100\\,\\%',leg:[['Z','Zeitgrad in %'],['t_\\text{Vorgabe}','Vorgabezeit'],['t_\\text{Ist}','tatsächlich benötigte Zeit']],e:'Über 100 % = schneller als Normalleistung.'}},
    {fx:{n:'Erforderlicher Zeitgrad ohne Mehrarbeit',tex:'Z_\\text{erf} = \\frac{K_\\text{B}}{K_\\text{ist}} \\cdot 100\\,\\%',leg:[['Z_\\text{erf}','nötiger Zeitgrad in %'],['K_\\text{B}','Kapazitätsbedarf in h'],['K_\\text{ist}','verfügbare Kapazität in h']]}},
    {bsp:{t:'Beispiel 1: Personalbedarf, Mehrarbeit, Zeitgrad',b:['Auftrag: 48 Getriebegehäuse montieren, Vorgabezeit 300 min/Stück, 5 Arbeitstage, 8 h/Tag, Anwesenheitsquote 95 %.','a) Kapazitätsbedarf = 48 × 300 min = 14.400 min ÷ 60 = 240 h.','Kapazität je MA = 5 Tage × 8 h × 0,95 = 38 h.','Personalbedarf = 240 h ÷ 38 h = 6,32 → aufgerundet 7 Mitarbeitende.','b) Es stehen nur 6 MA zur Verfügung: Bestand = 6 × 38 h = 228 h; Fehlstunden = 240 h − 228 h = 12 h.','Mehrarbeit je MA und Tag = 12 h ÷ (6 × 5 × 0,95) = 12 ÷ 28,5 = 0,42 h ≈ 25 min.','c) Ohne Mehrarbeit nötiger Zeitgrad = 240 h ÷ 228 h × 100 = 105,3 %.','Interpretation: 25 min Mehrarbeit pro Tag sind mit dem Arbeitszeitgesetz vereinbar (max. 10 h/Tag); ein Zeitgrad von 105 % ist für eingespielte Monteure erreichbar, aber ohne Puffer.']}},
    {bsp:{t:'Beispiel 2: Ausfall während des Auftrags',b:['Ausgangslage wie Beispiel 1, geplant mit 7 MA. Nach 2 Tagen fallen 2 MA krankheitsbedingt aus.','Geleistet in 2 Tagen: 7 × 2 × 8 h × 0,95 = 106,4 h; Restbedarf = 240 h − 106,4 h = 133,6 h.','Restkapazität mit 5 MA in 3 Tagen: 5 × 3 × 8 h × 0,95 = 114 h; Lücke = 19,6 h.','Mehrarbeit je MA und Tag = 19,6 h ÷ (5 × 3 × 0,95) = 1,38 h ≈ 1 h 23 min → Arbeitstag ca. 9,4 h, noch im Rahmen des ArbZG.','Alternativen: Springer aus der Vormontage umsetzen (Quali-Matrix prüfen), Leiharbeitnehmer, Samstagsarbeit, Teil fremd vergeben, mit dem Kunden Teillieferung vereinbaren. Mehrarbeit ist mitbestimmungspflichtig (§ 87 Abs. 1 Nr. 3 BetrVG).']}},
    {ol:['Strukturiert vorgehen bei einem neuen Auftrag (ohne Zahlen):','Pflichtenheft/Auftrag sichten: Welche Tätigkeiten, Fähigkeiten, Kenntnisse?','Zeitlichen Umfang und Termin bestimmen.','Auslastung des vorhandenen Personals und Status laufender Aufträge prüfen.','Prioritäten setzen: Was lässt sich verschieben?','Alternativen (intern, extern, Mehrarbeit) bewerten und entscheiden.']},
    {falle:'Aufrunden nicht vergessen (6,3 Personen gibt es nicht), die Quote nur einmal einrechnen und den Rechenweg mit Einheiten hinschreiben – das bringt auch bei Rechenfehlern Teilpunkte.'}
  ]},
  {t:'Ergebnisse der Bedarfsermittlung: Recruiting',h:'1.2 Ergebnisse der Ermittlung des Personalentwicklungsbedarfs – 1.2.1 Recruiting',pg:5,pdf:7,abb:[['Tab. 1.1 Vor- und Nachteile externer und interner Personalbeschaffung',6]],b:[
    {p:'Die Ergebnisse der Bedarfsermittlung ergänzen die reinen Mengen um die inhaltlichen Anforderungen. Sie konkretisieren die Personalsuche und helfen, vorhandene Potenziale auszuschöpfen – das wirkt auch positiv auf Motivation und Entwicklungschancen. Ziel ist, vom Plan zur tatsächlichen Verfügbarkeit des benötigten Personals zu kommen, über den internen oder den externen Arbeitsmarkt.'},
    {svg:{w:520,h:335,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="20" width="120" height="44" class="sk-body"/><text x="70" y="38" class="sk-t acc">Stelle frei</text><text x="70" y="56">Profil steht</text><polygon points="220,10 290,42 220,74 150,42" class="sk-body"/><text x="220" y="40">intern</text><text x="220" y="56">geeignet?</text><rect x="330" y="20" width="180" height="44" class="sk-body"/><text x="420" y="38" class="sk-t acc">extern suchen</text><text x="420" y="56">Portal, Agentur, Netz</text><rect x="130" y="110" width="180" height="44" class="sk-body"/><text x="220" y="128" class="sk-t acc">intern ausschreiben</text><text x="220" y="146">alte Stelle nachbesetzen</text><rect x="150" y="200" width="240" height="44" class="sk-body"/><text x="270" y="218" class="sk-t acc">Auswahl nach Profil</text><text x="270" y="236">Unterlagen, Gespräch, Probe</text><rect x="150" y="280" width="240" height="44" class="sk-body"/><text x="270" y="298" class="sk-t acc">Betriebsrat § 99 BetrVG</text><text x="270" y="316">dann Einarbeitung mit Pate</text><path d="M130,42 H148" class="sk-l" marker-end="url(#ar)"/><path d="M290,42 H328" class="sk-l" marker-end="url(#ar)"/><path d="M220,74 V108" class="sk-l" marker-end="url(#ar)"/><path d="M220,154 V198" class="sk-l" marker-end="url(#ar)"/><path d="M420,64 V222 H392" class="sk-l" marker-end="url(#ar)"/><path d="M270,244 V278" class="sk-f" marker-end="url(#ar)"/><text x="306" y="34">nein</text><text x="236" y="95">ja</text></g>',cap:'Entscheidungsweg bei einer freien Stelle'}},
    {tab:[['','Interne Beschaffung','Externe Beschaffung'],['Vorteile','geringere Kosten, schnelle Besetzung, Aufstiegschance motiviert Nachwuchs, hohe Bindung, geringere Fluktuation, Person ist bekannt (weniger Fehlbesetzung)','größere Auswahl, neue Impulse und Ideen, evtl. Wissen vom Wettbewerb, keine Besetzungskette, externe Vorgesetzte oft leichter anerkannt, ggf. Förderung bei Einstellung bestimmter Gruppen'],['Nachteile','weniger Auswahl, evtl. höhere Fortbildungskosten, Betriebsblindheit, Neid und Spannungen, Seilschaften statt objektiver Auswahl, Beförderungsautomatik ohne Leistungsanreiz, summarisch kein Effekt auf den quantitativen Bedarf','meist höhere Beschaffungskosten, längeres Verfahren, mehr Einarbeitung, Risiko der Fehleinschätzung, evtl. höhere Gehaltsforderung, hohe Fremdquote fördert Fluktuation'],['Wege','innerbetriebliche Ausschreibung (Aushang, Rundschreiben, Jobdatenbank), Versetzung, PE','Stellenanzeigen, Internet-Jobportale, Personalberater, Arbeitnehmerüberlassung, Bundesagentur für Arbeit, Social Media']]},
    {ul:['Häufig passt das Qualifikationsniveau der gefundenen Person noch nicht ganz zur Stelle → allgemeine PE-Maßnahmen und vor allem Anpassungsqualifizierung nötig.','E-Recruiting: Online-Stellenbörsen, Social-Media-Kanäle, berufliche Netzwerke (z. B. XING, LinkedIn) und eigene Karriereseiten gewinnen gegenüber Zeitungsanzeigen an Bedeutung.','M-Recruiting (Mobile Recruiting): Karriereseite und Bewerbung für das Smartphone – wichtig für Employer Branding (Arbeitgeberattraktivität) und für die mit digitalen Medien aufgewachsenen Jahrgänge.','Vorauswahl erfolgt zunehmend softwaregestützt: Bewerberprofile werden nach Algorithmen auf Eignung geprüft.','CV-Parsing („CV“ = Lebenslauf, „to parse“ = zerlegen): Software liest Bewerbungs- oder Stammdaten aus, bringt sie in eine einheitliche Struktur und zeigt Lücken.','Nutzen CV-Parsing: Bewerbende werden nach Fakten verglichen (Chancengleichheit); Recruiter sparen Zeit, Abschlüsse und Fachkenntnisse sind verdichtet, Beurteilungsfehler werden seltener.','Kritik: Bewerbungen werden auf Algorithmen hin optimiert; der persönliche Eindruck erfahrener Recruiter geht verloren.','Auswahlgespräch vorbereiten: Anforderungsprofil, Leitfragen, Analyse der Unterlagen und Zeugnisse (Lücken, Zeugnissprache), Gesprächsnotiz.','Rechtlich: AGG (neutrale Ausschreibung, keine unzulässigen Fragen), DSGVO bei Bewerberdaten; Betriebsrat: Ausschreibung intern verlangen (§ 93), Auswahlrichtlinien (§ 95), Zustimmung bei Einstellung/Versetzung (§ 99 BetrVG).']},
    {bsp:{t:'Beispiel: Schichtführer Zerspanung besetzen',b:['Bedarf: Der Schichtführer der Spätschicht wechselt in die Arbeitsvorbereitung.','Intern: Zwei Facharbeiter kommen infrage; einer hat bereits vertreten und gute Akzeptanz → interne Ausschreibung (Aushang, Intranet).','Vorteil: schnell besetzt, Prozesswissen da, Signal an das Team „Aufstieg ist möglich“.','Folge bedenken: Seine Facharbeiterstelle wird frei (Besetzungskette) → extern eine Zerspanungsfachkraft über Jobportal und Agentur für Arbeit suchen.','Qualifizierung des neuen Schichtführers: Führungsgrundlagen-Seminar + Begleitung durch den Meister in den ersten 3 Monaten.']}},
    {falle:'„Intern ist immer besser“ ist falsch: Wer intern besetzt, schafft an anderer Stelle eine neue Lücke – summarisch ändert sich der quantitative Bedarf nicht. In der Prüfung werden Vor- und Nachteile beider Wege gern als Tabelle verlangt; E- und M-Recruiting sowie Zeugnisanalyse und Gesprächsvorbereitung sind beliebte Themen.'}
  ]},
  {t:'Anpassungsqualifizierung',h:'1.2.2 Anpassungsqualifizierung',pg:7,pdf:9,b:[
    {p:'Digitalisierung und Technik verändern Arbeitsplätze immer schneller; Wissen veraltet in kurzer Zeit. Anpassungsqualifizierung hält die Kenntnisse für die bestehende Stelle aktuell. Ziel: Änderungen der Anforderungen möglichst früh erkennen und Wissenslücken systematisch schließen.'},
    {svg:{w:520,h:280,body:'<g class="sk-t" text-anchor="middle"><rect x="40" y="190" width="150" height="50" class="sk-body"/><text x="115" y="210" class="sk-t acc">Facharbeiter</text><text x="115" y="228">heutige Stelle</text><rect x="330" y="190" width="180" height="50" class="sk-body"/><text x="420" y="210" class="sk-t acc">Anpassung</text><text x="420" y="228">gleiche Stelle, neu</text><rect x="40" y="40" width="150" height="50" class="sk-body"/><text x="115" y="60" class="sk-t acc">Aufstieg</text><text x="115" y="78">Meister, Techniker</text><rect x="330" y="40" width="180" height="50" class="sk-body"/><text x="420" y="60" class="sk-t acc">Umschulung</text><text x="420" y="78">anderer Beruf</text><path d="M190,215 H328" class="sk-f" marker-end="url(#ar)"/><path d="M115,190 V92" class="sk-f" marker-end="url(#ar)"/><path d="M190,195 L328,88" class="sk-c" marker-end="url(#ar)"/><text x="260" y="265">gleiche Ebene →</text><text x="22" y="140" transform="rotate(-90 22 140)">höhere Ebene →</text></g>',cap:'Arten der Qualifizierung im Vergleich'}},
    {tab:[['Art','Ziel','Beispiele Metall'],['Anpassungsqualifizierung','Kompetenz für die bestehende Stelle aktuell halten','neue CNC-Steuerung, geänderte Norm, neues ERP-Release, Gefahrstoff-Unterweisung'],['Aufstiegsqualifizierung','Befähigung für eine höherwertige Funktion (Führung oder höhere Tarifgruppe)','Industriemeister, Techniker, Führungstraining, Qualifikation für höher eingruppierte Tätigkeit'],['Umschulung','Befähigung für einen anderen Beruf','Lagerhelfer wird Maschinen- und Anlagenführer']]},
    {tab:[['Planbarkeit','Beispiel','Reaktion'],['gut vorhersehbar','Jahreswechsel, angekündigte Investition','langfristig Seminar einplanen'],['vorhersehbar, Termin unsicher','Gesetzesänderung, Software-Release','beobachten, Budget vorhalten'],['kaum vorhersehbar','Reklamation, Störung, neue Kundenforderung','sofortige Unterweisung, Coaching am Platz']]},
    {ul:['Anlässe für das Gespräch über neue Aufgaben: jährliches Mitarbeitergespräch, Aktualisierung der Stellenbeschreibung.','Voraussetzung jeder vorausschauenden Planung: Dialog zwischen Führungskraft und Mitarbeitenden über sich ändernde Anforderungen.','Aufstiegsqualifizierung muss nicht in Führung münden – auch ein höherwertiger Tätigkeitsbereich zählt.','In vielen Betrieben wird mindestens einmal jährlich über Weiterbildung gesprochen.','Förderung: Aufstiegs-BAföG (Meister, Techniker); Weiterbildungsförderung Beschäftigter durch die Agentur für Arbeit (§ 82 SGB III).','Betriebsrat: Beratung bei Berufsbildung (§§ 96, 97 BetrVG); plant der Arbeitgeber Änderungen, durch die Kenntnisse nicht mehr reichen, bestimmt der BR bei der Einführung von Qualifizierung mit (§ 97 Abs. 2); Durchführung und Teilnehmerauswahl betrieblicher Bildung: § 98 BetrVG.']},
    {bsp:{t:'Beispiel: Umstellung auf neue Schweißnorm und neue Stromquellen',b:['Auslöser: Kunde verlangt ab Januar Schweißnachweise nach aktueller Norm; zugleich werden 4 neue Inverter-Stromquellen geliefert.','Gut planbar: Herstellerschulung zur Bedienung der Stromquellen (1 Tag) für alle 8 Schweißer, kurz vor der Lieferung.','Termin unsicher: Prüfungen der Schweißer nach neuer Norm – Prüfstelle anfragen, Budget reservieren.','Kurzfristig: Bei ersten Nahtfehlern Unterweisung durch den Schweißfachmann direkt am Arbeitsplatz.','Dokumentation: Quali-Matrix und Schweißerprüfungsliste aktualisieren.']}},
    {merke:'Anpassung = gleiche Stelle, neuer Stand; Aufstieg = höherwertige Funktion; Umschulung = neuer Beruf.'}
  ]},
  {t:'Bedeutung der Personalentwicklung für den Unternehmenserfolg',h:'2.1 Bedeutung der Personalentwicklung für den Unternehmenserfolg',pg:10,pdf:12,b:[
    {p:'Kontinuierliche PE trägt dazu bei, anspruchsvolle Ziele und Qualität zu erreichen, die Wettbewerbs- und Leistungsfähigkeit durch Anpassung an Technik und Markt zu erhalten und die personelle Zukunft zu sichern (Motivation erhalten, ungenutzte Potenziale heben). Der Meister muss das für seinen Bereich herunterbrechen und gegenüber Vorgesetzten, Personalabteilung oder Geschäftsführung begründen können – immer aus zwei Perspektiven: Interessen der Mitarbeitenden und Interessen des Unternehmens.'},
    {tab:[['Entwicklung','Folge für die PE'],['Sorge um den Arbeitsplatz','viele qualifizieren sich weiter; Gefahr: Herrschaftswissen wird gehortet und hemmt Innovation'],['veränderte Schulzeit und Bachelor-Abschlüsse','Berufseinsteiger bringen andere Wissensbasis mit → betriebliche Programme verstärken'],['hohe Standortkosten in Deutschland','einfache Tätigkeiten wandern ab; punkten mit Dienstleistung, Ideen, Innovation'],['kürzerer Imitationsschutz','höhere Innovationsdichte, schnelleres Lernen nötig'],['Globalisierung und brüchige Lieferketten','Know-how wieder im Land halten; Spezialisten mit soliden Grundlagen'],['Digitalisierung, Agilität, Industrie 4.0','Vernetzung von Produktion, Logistik, Kunden verändert Arbeit, Zusammenarbeit und Führung; Mitarbeitende schulen, neue Führung lernen'],['Wegfall von Tätigkeiten','Beschäftigungsfähigkeit (Employability) intern und extern sichern – Teil der Fürsorge']]},
    {ul:['Lebenslanges Lernen: Wissen erwerben ist das eine, es aktuell halten das andere; der Umgang mit Wissen wird noch wichtiger.','Die PE-Abteilung soll Wege für kollegialen Wissensaustausch schaffen; Führungskräfte halten ihre Leute zum Austausch an.','Einarbeitungsprogramme und kontinuierliche Entwicklung im Arbeitsumfeld werden für Führungskräfte zum zentralen Faktor.','Das klassische Seminar ist nur noch eine Lernform neben E-Learning und Lernen am Arbeitsplatz.']},
    {bsp:{t:'Beispiel: PE gegenüber der Geschäftsleitung begründen',b:['Vorhaben: Zwei Zerspaner sollen eine 5-Achs-Programmierschulung (je 5 Tage) erhalten.','Argument Unternehmen: Bisher werden komplexe Teile extern programmiert (ca. 18.000 €/Jahr); Know-how bleibt im Haus, Durchlaufzeit sinkt.','Argument Wettbewerb: Kunden fragen zunehmend 5-Achs-Teile an; ohne Kompetenz verlieren wir Aufträge.','Argument Mitarbeitende: Entwicklungsperspektive, Bindung, weniger Fluktuationsrisiko bei gesuchten Fachkräften.','Gegenüber dem Team: Wissen wird anschließend weitergegeben (Kopfmonopol vermeiden).']}},
    {merke:'PE ist eine unternehmerische Funktion mit wachsender Bedeutung. Wer sie beantragt, argumentiert mit Unternehmenszielen – und vergisst den Nutzen für die Person nicht.'}
  ]},
  {t:'Ziele der Personalentwicklung',h:'2.2 Ziele der Personalentwicklung',pg:12,pdf:14,abb:[['Beispiel: Ableitung von PE-Zielen aus Unternehmenszielen',14]],b:[
    {p:'Personalentwicklung umfasst alle Maßnahmen der Bildung, der Förderung und der Organisationsentwicklung, die zielgerichtet, systematisch und methodisch geplant, umgesetzt und bewertet werden (Definition nach Becker). Bildung meint dabei die sich ständig entwickelnden Fähigkeiten und Eigenschaften einer Persönlichkeit.'},
    {svg:{w:520,h:270,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="10" width="500" height="250" class="sk-body"/><rect x="30" y="70" width="460" height="175" class="sk-body"/><rect x="50" y="130" width="420" height="100" class="sk-body"/><text x="20" y="32" text-anchor="start" class="sk-t acc">Organisationsentwicklung (PE im weiten Sinn)</text><text x="20" y="54" text-anchor="start">Teamentwicklung, Projekt- und Gruppenarbeit, Strukturen</text><text x="40" y="92" text-anchor="start" class="sk-t acc">Förderung</text><text x="40" y="114" text-anchor="start">Einarbeitung, Rotation, Nachfolge, MA-Gespräch, Coaching</text><text x="60" y="152" text-anchor="start" class="sk-t acc">Bildung (PE im engeren Sinn)</text><text x="60" y="176" text-anchor="start">Ausbildung, Weiterbildung, Umschulung,</text><text x="60" y="196" text-anchor="start">Anlernen, Führungskräfteausbildung</text></g>',cap:'Bildung, Förderung und Organisationsentwicklung als Schalen der PE'}},
    {tab:[['Ziele aus Mitarbeitersicht','Ziele aus Unternehmenssicht'],['fachliche und persönliche Qualifikation erhalten und verbessern','Fach- und Führungskräftebestand sichern'],['ungenutzte Potenziale aktivieren','Nachwuchsführungskräfte und Spezialisten erkennen und vorbereiten'],['neue oder erweiterte Aufgaben übernehmen','Anpassung an Technik und Markt'],['bessere Karriere- und Laufbahnchancen','größere Unabhängigkeit vom externen Arbeitsmarkt'],['geringeres Risiko des Arbeitsplatzverlusts','Qualifikation der Belegschaft erhalten und verbessern'],['bessere Chancen am Arbeitsmarkt, mehr Mobilität','Mitarbeiterzufriedenheit und Leistungsmotivation steigern'],['Selbstverwirklichung, Entfaltung der Persönlichkeit','Wettbewerbsfähigkeit sichern, Fehlbesetzungen und Defizite aufdecken'],['mehr Prestige','Schlüsselqualifikationen vermitteln, Veränderungsbereitschaft fördern'],['Aufgaben nach Eignung und Neigung','weniger Fluktuation und damit geringere Beschaffungskosten'],['höheres Einkommen','Kooperation und Kommunikation verbessern, Mitarbeitende binden']]},
    {p:'PE und Weiterbildung sind kein Selbstzweck, sondern Mittel zur Erreichung der strategischen Unternehmensziele. Deshalb werden PE-Ziele unternehmensspezifisch formuliert (z. B. Internationalisierung mit Sprach- und interkulturellen Trainings oder Begleitung eines Technologiewechsels) und kaskadenartig auf Bereiche heruntergebrochen.'},
    {svg:{w:520,h:230,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="8" width="190" height="36" class="sk-body"/><text x="105" y="31" class="sk-t acc">Unternehmensziel</text><text x="215" y="31" text-anchor="start">Lieferzeit für Ersatzteile halbieren</text><rect x="10" y="70" width="190" height="36" class="sk-body"/><text x="105" y="93">Bereichsziel</text><text x="215" y="93" text-anchor="start">Rüstzeit an der CNC-Zelle um 30 % senken</text><rect x="10" y="132" width="190" height="36" class="sk-body"/><text x="105" y="155">PE-Ziel (SMART)</text><text x="215" y="155" text-anchor="start">Bis Juni rüsten 2 weitere MA selbstständig</text><rect x="10" y="194" width="190" height="36" class="sk-body"/><text x="105" y="217">Lernziel</text><text x="215" y="217" text-anchor="start">MA richtet Werkstück-Nullpunkt sicher ein</text><path d="M105,44 V68" class="sk-l" marker-end="url(#ar)"/><path d="M105,106 V130" class="sk-l" marker-end="url(#ar)"/><path d="M105,168 V192" class="sk-l" marker-end="url(#ar)"/></g>',cap:'Zielkaskade mit eigenem Beispiel'}},
    {ul:['Leitfragen zur Ableitung: Wie will sich der Bereich aufstellen? Welche Ziele müssen dafür erreicht werden? Welcher quantitative Personalbedarf folgt? Welche qualitativen Anforderungen? Welche Führungskräfte, Mitarbeitenden, Projektleitungen braucht es? Was müssen sie wissen, können, wollen? Welche Verhaltensweisen sollen gezeigt werden und wie wird das unterstützt? Welche Qualifikationen fehlen? Welche Lernziele folgen?','PE-Ziele hängen ab von Unternehmenszielen, vom Potenzial der Belegschaft und von den Chancen, Externe zu gewinnen.','People Analytics: Big-Data-Auswertungen im Personalbereich zeigen Auffälligkeiten (z. B. hohe Leistung, lange keine Entwicklung → Fluktuationsrisiko) und geben Empfehlungen – die Entscheidung trifft der Mensch, menschliches Verhalten folgt nicht immer berechenbaren Regeln.','Als Meister plant man meist PE für den eigenen Bereich oder einzelne Personen, nicht unternehmensweit – den Gesamtzusammenhang sollte man trotzdem kennen.']},
    {tab:[['SMART','Bedeutung'],['S – spezifisch','eindeutig, nicht „geben Sie Ihr Bestes“'],['M – messbar','zählen, wiegen, messen oder abgestuft beobachtbar'],['A – anspruchsvoll (auch: akzeptiert)','etwas mehr als ohne Anstrengung möglich'],['R – realistisch','mit vorhandenen Mitteln erreichbar'],['T – terminiert','an einen Termin gebunden']]},
    {bsp:{t:'Beispiel: Aus vagen Wünschen ein SMART-Ziel machen',b:['Vage: „Herr B. soll besser programmieren können.“','Spezifisch: Er erstellt Programme für Drehteile mit Zyklen und Unterprogrammen an der neuen Steuerung.','Messbar: mindestens 10 Programme ohne Korrektur durch den Einrichter.','Anspruchsvoll und realistisch: Grundkenntnisse vorhanden, Kurs + Übungszeit von 2 h/Woche eingeplant.','Terminiert: bis 30. Juni.','SMART-Ziel: „Bis 30.06. erstellt Herr B. für Drehteile der Familie A mindestens 10 Programme mit Zyklen und Unterprogrammen, die ohne Korrektur laufen.“']}},
    {merke:'Ziele und daraus die Bewertungskriterien unterscheiden sich von Betrieb zu Betrieb und von Bereich zu Bereich. Ohne messbares Ziel lässt sich PE-Erfolg nicht bewerten.'}
  ]},
  {t:'Kriterien der Bewertung im Managementregelkreis',h:'2.3 Kriterien der Bewertung',pg:15,pdf:17,abb:[['Abb. 2.1 Managementregelkreis',15],['Tab. 2.1 Planung',15],['Tab. 2.2 Steuerung',16],['Tab. 2.3 Kontrolle',16]],b:[
    {p:'Wirksam ist eine Qualifizierung, wenn sie zum Unternehmenserfolg beiträgt. Für die ganzheitliche Erfolgsbewertung gibt es sechs Evaluationsebenen (siehe Evaluation). Für den Entwicklungsprozess selbst eignet sich der Managementregelkreis Planung – Steuerung – Kontrolle.'},
    {ul:['Mögliche Erfolgsbeiträge: höhere Umsätze, geringere Kosten, bessere Qualität, kürzere Durchlaufzeiten, höhere Stückzahlen, weniger Ausschuss und Fehler, bessere Führung und Zusammenarbeit, höhere Zufriedenheit und Motivation, nachhaltigeres Wirtschaften, Umsetzung der Digitalisierung.']},
    {svg:{w:520,h:260,body:'<g class="sk-t" text-anchor="middle"><rect x="180" y="10" width="160" height="50" class="sk-body"/><text x="260" y="31" class="sk-t acc">Bedarf + Ziele</text><text x="260" y="49">(SMART)</text><rect x="365" y="105" width="145" height="50" class="sk-body"/><text x="437" y="126" class="sk-t acc">Planung</text><text x="437" y="144">Budget, Anbieter</text><rect x="170" y="200" width="180" height="50" class="sk-body"/><text x="260" y="221" class="sk-t acc">Steuerung</text><text x="260" y="239">Durchführung, Kosten</text><rect x="10" y="105" width="150" height="50" class="sk-body"/><text x="85" y="126" class="sk-t acc">Kontrolle</text><text x="85" y="144">Transfer, Nutzen</text><path d="M340,35 L435,102" class="sk-f" marker-end="url(#ar)"/><path d="M437,155 L353,223" class="sk-f" marker-end="url(#ar)"/><path d="M170,225 L87,158" class="sk-f" marker-end="url(#ar)"/><path d="M85,105 L177,37" class="sk-f" marker-end="url(#ar)"/><text x="260" y="128">Regelkreis</text><text x="260" y="146">der PE</text></g>',cap:'Regelkreis: Ergebnisse der Kontrolle fließen in den nächsten Bedarf ein'}},
    {tab:[['Phase','Kriterium','Prüffrage','Beispiele'],['Planung','Bedarfsfeststellung','Richtiger Bedarf, richtig erhoben?','Bedarf aus Mitarbeitergesprächen bündeln, digitaler Abgleich Stelle–Kompetenz, People Analytics'],['Planung','Wirtschaftlichkeit','Wie günstig ist der Bedarf zu decken?','Preis-Leistung von Anbietern und Lernformen (Fachbuch vs. Seminar)'],['Planung','Budget','Welche Mittel sind bereitzustellen?','Marktpreise für Trainings, Freistellung von der Arbeitszeit'],['Steuerung','Durchführungsqualität','Wird der Bedarf gut bedient?','systematische Auswahl von Trainern und Instituten'],['Steuerung','Kostenkontrolle','Wie entwickeln sich die Kosten?','Soll-Ist-Vergleich des Budgets'],['Kontrolle','Transfer','Wird Gelerntes umgesetzt?','Transferinstrumente, Apps zur Transferplanung, Feedback'],['Kontrolle','Wirtschaftlichkeit','Lohnt sich die Investition?','Zielerreichung dokumentieren, Nutzen schätzen, Kosten-Nutzen-Rechnung']]},
    {ul:['Planung, Steuerung und Kontrolle werden zunehmend digital unterstützt.','Weitere Aktivitäten in diesen Phasen liegen meist bei der PE- bzw. Weiterbildungsabteilung.','Rolle des Meisters: nach der Zufriedenheit fragen, Austausch über Lernerfahrungen, Gelegenheit zur Anwendung geben, beim Transfer unterstützen.','ROI und Bildungsrendite berechnen Spezialisten der Personalabteilung – für Transfer und die Besprechung der Umsetzung ist der Meister verantwortlich.']},
    {bsp:{t:'Beispiel: Regelkreis für eine Kranführer-Schulung',b:['Planung: Unterweisungsnachweise zeigen 6 Mitarbeitende ohne gültige Kranschein-Auffrischung; zwei Anbieter verglichen (Inhouse 1.800 € vs. extern 6 × 390 € = 2.340 €) → Inhouse gewählt, Budget 1.800 € plus 6 × 8 h Freistellung.','Steuerung: Trainer mit Referenzen aus der Branche; Zwischenabfrage Budget: Raum intern, keine Zusatzkosten.','Kontrolle: Praktische Prüfung am Hallenkran bestanden; nach 4 Wochen Beobachtung beim Anschlagen; keine Beinahe-Unfälle im Quartal.','Rückkopplung: Auffrischung künftig alle 12 Monate fest im Jahresplan.']}},
    {merke:'Planung fragt nach Bedarf, Wirtschaftlichkeit und Budget – Steuerung nach Qualität und Kosten – Kontrolle nach Transfer und Nutzen.'}
  ]},
  {t:'Potenzialeinschätzung: Leistung und Potenzial',h:'3.1 Potenzialeinschätzung als Baustein des Personalentwicklungskonzepts',pg:18,pdf:20,abb:[['Tab. 3.1 Leistung vs. Potenzial',19]],b:[
    {p:'Vorausschauend führen heißt auch, das Potenzial der Mitarbeitenden einzuschätzen. Weil Fachkräfte knapp sind („War for Talents“), müssen Betriebe vorhandene Potenziale im eigenen Haus suchen, z. B. für Nachfolgeplanung und Schlüsselfunktionen. Eine Potenzialaussage ist nur sinnvoll mit dem Zusatz: Potenzial wofür?'},
    {svg:{w:520,h:210,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="30" width="220" height="90" class="sk-body"/><text x="120" y="50" class="sk-t acc">Leistungsbeurteilung</text><text x="120" y="70">beobachtetes Verhalten</text><text x="120" y="88">Ergebnisse vs. Ziele</text><text x="120" y="108">→ Entgelt, Feedback</text><rect x="290" y="30" width="220" height="90" class="sk-body"/><text x="400" y="50" class="sk-t acc">Potenzialeinschätzung</text><text x="400" y="70">Eignung für künftige</text><text x="400" y="88">Aufgaben – wofür, bis wann?</text><text x="400" y="108">→ Förderung, Nachfolge</text><path d="M260,160 H22" class="sk-l" marker-end="url(#ar)"/><path d="M260,160 H498" class="sk-l" marker-end="url(#ar)"/><path d="M260,148 V172" class="sk-l thick"/><text x="260" y="192" class="sk-t acc">heute</text><text x="80" y="192">Vergangenheit</text><text x="440" y="192">Zukunft</text></g>',cap:'Leistung blickt zurück, Potenzial blickt nach vorn'}},
    {tab:[['Leistung','Potenzial'],['belegt im Nachhinein den richtigen Mitteleinsatz','prognostiziert die Bewältigung künftiger Aufgaben'],['Basis für Entgelt und Zulagen','erklärt, welcher Leistungsstand mittel-/langfristig erreichbar ist'],['zeigt Bedarf an neuen oder veränderten Aufgaben','sichert den künftig richtigen Einsatz'],['ganze Belegschaft, laufend im festen Turnus','ausgewählte Personen, Neuerhebung etwa alle drei Jahre'],['vergangenheitsorientiert, verhaltensbezogen','zukunftsorientiert, persönlichkeitsbezogen'],['überwiegend quantitativ an Maßstäben','qualitativ beschreibend, möglichst wertneutral'],['äußeres Verhalten („Oberflächenbefund“)','innere Strebungen und Neigungen („Tiefenbefund“)'],['vor allem fachliche Leistung','vor allem überfachliche Qualifikation, erfordert Menschenkenntnis']]},
    {ul:['Ablauf: Erste Einschätzung durch die disziplinarische Führungskraft → Prüfung in einer Personalrunde mehrerer Führungskräfte (meist von HR moderiert) → ggf. Validierung im AC, DC, Mitarbeiterentwicklungsgespräch.','Hohe Leistung ist nicht automatisch Potenzial; beides wird oft vermischt.','Zwei Positionen: Potenzialanalyse (wissenschaftlich abgesicherte Kriterien, Tests) vs. Potenzialeinschätzung (Zutrauen in eine Person). Kritik an der Analyse: Korrelation ist keine Ursache; Kritik an der Einschätzung: uneinheitliche Maßstäbe bis Willkür. Praxis: beides kombinieren, Beobachtungstraining, Mehraugenprinzip in Personal- oder Talentportfolios.','Ausgangspunkt ist die Führungsbeziehung zwischen Vorgesetztem und Mitarbeitendem.','Potenzialaussagen gelten für einen Zeitraum – manche entfalten Potenzial später. Je endgültiger eine negative Aussage wirkt, desto größer der Frust. Fristigkeit transparent machen.','Positive Einschätzung: Signal des Zutrauens, Freude an eigener Entwicklung, interessante Aufgaben, Karriere- und Gehaltsentwicklung – starkes Motivationspotenzial.','Das Gespräch darüber bleibt Aufgabe des disziplinarischen Vorgesetzten; kritisch, wenn Dritte Potenzial erkennen, der Vorgesetzte aber schweigt, delegiert oder nur jemanden für eine ungeliebte Aufgabe sucht.','In agilen Strukturen (Scrum, hybride Projekte) kennen disziplinarische Vorgesetzte die Arbeit oft weniger; Scrum Master, Matrix-Verantwortliche, Peers oder Kunden liefern mehr Informationen. Scrum Master führen ohne formale Autorität; gefragt sind Beobachten, Zuhören, empathische Kommunikation, Mut, Frustrationstoleranz – Rollen: lehren, Mentor sein, coachen, Konflikte mediieren, Gruppen moderieren, Organisationsdesign beraten.']},
    {bsp:{t:'Beispiel: Nachfolger für den Vorarbeiter Montage',b:['Kandidat 1: bester Monteur, sehr schnell und genau, aber ungeduldig mit Kollegen → hohe Leistung, Führungspotenzial unklar.','Kandidatin 2: solide Leistung, organisiert schon jetzt Urlaubsvertretungen, wird bei Problemen von Kollegen gefragt → Hinweise auf Führungspotenzial.','Kandidat 3: seit 4 Monaten im Betrieb, sehr gute Ausbildung, beliebt → Potenzial vermutet, aber noch nicht belegt; in einem Jahr erneut einschätzen.','Vorgehen: Einschätzung des Meisters in der Personalrunde mit zwei anderen Meistern abgleichen; Kandidatin 2 erhält zunächst die Stellvertretung als Bewährungsaufgabe.','Gespräch mit Kandidat 1: Wertschätzung seiner Fachleistung, Entwicklung als Spezialist/Einrichter anbieten.']}},
    {falle:'Leistung und Potenzial getrennt begründen: „Leistung zeigt, was jemand heute kann – Potenzial, was er künftig übernehmen kann.“ Der beste Facharbeiter ist nicht automatisch der beste Vorgesetzte.'}
  ]},
  {t:'Personalgespräche und Gesprächsführung',h:'3.2 Instrumente und Methoden',pg:22,pdf:24,abb:[['Beispiel: Schritt für Schritt durch das Gespräch',23]],b:[
    {p:'Führung geschieht über Kommunikation. Führungskräfte führen viele Arten von Personalgesprächen, die unterschiedliche Ziele, Verläufe und Wirkungen auf die Motivation haben – deshalb sorgfältig unterscheiden.'},
    {tab:[['Gesprächsart','Ziel'],['Bewerbungsgespräch','Eignung klären'],['Gehaltsgespräch','Entgelt verhandeln'],['Unterweisung','Arbeitsweise und Sicherheit vermitteln'],['Aufgabendelegation','Aufgabe, Kompetenz, Verantwortung übertragen'],['Kritikgespräch, mündliche Ermahnung','Fehlverhalten ansprechen, Änderung vereinbaren'],['Abmahnungs-/Kündigungsgespräch','arbeitsrechtliche Konsequenz mitteilen'],['Beurteilungsgespräch','Leistung rückmelden, Defizite → Qualifizierung'],['Beratungs-/Entwicklungsgespräch','Karriere- und Entwicklungsschritte ausloten'],['Betreuungsgespräch','Feedback und Rat, wenn die Umsetzung „hakt“']]},
    {ul:['Kritische Gespräche nicht im Affekt: wenn keine Gefahr im Verzug ist, eine Nacht darüber schlafen.','Termin und Themen rechtzeitig ankündigen; Mitarbeitende ebenfalls zur Vorbereitung auffordern.','Störungsfreier Raum (Telefon umstellen, keine Dritten), bei längeren Gesprächen Getränke.','Genug Zeit einplanen, pünktlich sein, höflich und freundlich – gerade bei ernsten Themen.','In Online-Formaten ist eine klare Struktur noch wichtiger.']},
    {svg:{w:520,h:160,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="10" width="150" height="50" class="sk-body"/><text x="85" y="31" class="sk-t acc">1 Vorbereitung</text><text x="85" y="49">Termin, Raum, Daten</text><rect x="185" y="10" width="150" height="50" class="sk-body"/><text x="260" y="31" class="sk-t acc">2 Einstieg</text><text x="260" y="49">Kontakt, Klima</text><rect x="360" y="10" width="150" height="50" class="sk-body"/><text x="435" y="31" class="sk-t acc">3 Anlass + Ziel</text><text x="435" y="49">Ablauf, Zeitrahmen</text><rect x="360" y="100" width="150" height="50" class="sk-body"/><text x="435" y="121" class="sk-t acc">4 Sichtweisen</text><text x="435" y="139">erst MA, dann FK</text><rect x="185" y="100" width="150" height="50" class="sk-body"/><text x="260" y="121" class="sk-t acc">5 Lösung</text><text x="260" y="139">Ursachen, Optionen</text><rect x="10" y="100" width="150" height="50" class="sk-body"/><text x="85" y="121" class="sk-t acc">6 Abschluss</text><text x="85" y="139">Wer? Was? Bis wann?</text><path d="M160,35 H183" class="sk-l" marker-end="url(#ar)"/><path d="M335,35 H358" class="sk-l" marker-end="url(#ar)"/><path d="M435,60 V98" class="sk-l" marker-end="url(#ar)"/><path d="M360,125 H337" class="sk-l" marker-end="url(#ar)"/><path d="M185,125 H162" class="sk-l" marker-end="url(#ar)"/></g>',cap:'Phasen eines strukturierten Mitarbeitergesprächs'}},
    {tab:[['Phase','Was der Meister tut'],['Kontakt und Einleitung','begrüßen, gemeinsam setzen, kurzer persönlicher Einstieg, nicht lange um den heißen Brei reden'],['Orientierung','Anlass und Gesprächsziel nennen, Vorgehen und Zeitrahmen erläutern'],['Mitarbeitersicht','zuerst den Mitarbeitenden schildern lassen, nicht unterbrechen, Notizen, nur Verständnisfragen'],['eigene Sicht','eigene Wahrnehmung schildern (bestätigen, ergänzen, widersprechen); Raum für Gefühle lassen, nicht kommentieren; dann zum Kern überleiten'],['Lösung','Unterschiede und Ursachen herausarbeiten, beidseitig tragbare Lösung, offen für neue Argumente, Zwischenergebnisse sichern'],['Abschluss','zusammenfassen, schriftlich festhalten: Wer macht was bis wann?'],['Auswertung','Ziele erreicht? Was veranlassen? Was lerne ich für das nächste Gespräch?']]},
    {bsp:{t:'Beispiel: Kritikgespräch wegen fehlender Erstmusterprüfung',b:['Vorbereitung: Ein Monteur hat zweimal ohne Erstteilfreigabe in Serie gefertigt; Fakten (Datum, Auftrag, Ausschuss 34 Teile) notieren, Termin für den nächsten Morgen ansetzen, Besprechungsraum reservieren.','Einleitung: „Ich möchte mit Ihnen über die Freigabe am Bearbeitungszentrum 3 sprechen. Ziel: Wir verstehen beide, was passiert ist, und vereinbaren, wie es künftig läuft. Wir haben 30 Minuten.“','Mitarbeitersicht: Er berichtet von Zeitdruck in der Spätschicht und fehlendem Prüfer.','Eigene Sicht: Ausschusskosten und Kundenrisiko darstellen; Ärger zulassen.','Lösung: Gemeinsam vereinbart – bei fehlendem Prüfer ruft er den Schichtführer an; Prüfplatz-Checkliste wird ergänzt.','Abschluss: Vereinbarung schriftlich, Kontrolle bei den nächsten 3 Rüstvorgängen durch den Meister.']}},
    {merke:'Erst zuhören, dann eigene Sicht – und am Ende immer: Wer? Was? Bis wann? schriftlich.'}
  ]},
  {t:'Mitarbeiterjahresgespräch und Entwicklungsgespräch',h:'3.2 Instrumente und Methoden',pg:24,pdf:26,abb:[['Abb. 3.1 Bestandteile eines Mitarbeitergesprächs',24],['Beispiel: Gesprächsbogen Karriere und Entwicklung',24]],b:[
    {p:'Das jährliche Mitarbeitergespräch ist das zentrale Führungsinstrument. Es ergänzt die tägliche, eher formlose Kommunikation und hat meist drei Bausteine.'},
    {tab:[['Baustein','Inhalt'],['Leistungs- und Verhaltensbeurteilung (abgelaufene Periode)','vereinbarte Ziele und Verhaltensabsprachen mit dem tatsächlich Erreichten abgleichen'],['Zielvereinbarung (kommende Periode)','Ziele und Verhaltensvereinbarungen festlegen; Stellenbeschreibung auf Aktualität prüfen'],['Entwicklungswünsche und Weiterbildung','Maßnahmen gegen Defizite oder zur Vorbereitung auf neue Aufgaben; Karrierewünsche (gleiche Ebene, Projekt, Führung); Mobilität (Standort, Deutschland, Europa, weltweit – kurz-, mittel-, langfristig)']]},
    {ul:['Gesprächsbogen zu Karriere und Entwicklung: Stärken, Verbesserungsmöglichkeiten, Entwicklungswünsche (Jobfit, fachliche Vertiefung, Projektarbeit, Führung), Mobilität; Rückblick auf durchgeführte Maßnahmen der letzten 12 Monate (auch ungeplante); vereinbarte Maßnahmen für das nächste Jahr; Unterschriften, Kopie an PE.','Karriereentscheidungen nicht allein durch die Führungskraft: Potenzial evtl. noch nicht bestätigt, künftig freie Positionen sind ihr oft nicht bekannt.','Mitarbeitergespräche haben auch beratenden Charakter: Karriere- und Entwicklungsmöglichkeiten kurz-, mittel-, langfristig aufzeigen.','Vereinbarte Maßnahmen nachhalten ist Betreuungsaufgabe der Führungskraft (und der PE-Abteilung).','Interessen der Mitarbeitenden können sich ändern – regelmäßig mit den Anforderungen des Unternehmens abgleichen.','Alternativen: Arbeitsbögen, mündliche oder schriftliche Befragungen von Mitarbeitenden und Vorgesetzten.','PE ist nicht delegierbare Führungsverantwortung; die erste Sichtung von Mitarbeiterpotenzial ist originäre Aufgabe der Führungskraft.']},
    {bsp:{t:'Beispiel: Jahresgespräch mit einer Maschinen- und Anlagenführerin',b:['Rückblick: Ziel „Rüstzeit an Linie 2 unter 45 min“ erreicht (Ø 41 min); Verhaltensabsprache „Schichtübergabe schriftlich“ zu 80 % eingehalten.','Ausblick: Neues Ziel „Instandhaltungsplan TPM für Linie 2 bis 31.10. mitgestalten“; Stellenbeschreibung um Erstteilprüfung ergänzt.','Entwicklung: Stärke Organisation, Verbesserungsfeld Moderation; Wunsch nach Projektarbeit; mobil nur am Standort.','Vereinbart: Moderationsseminar (2 Tage, Q2), Mitarbeit im KVP-Team, Statusgespräch nach 6 Monaten.','Bogen unterschreiben beide, Kopie an die Personalentwicklung.']}},
    {merke:'Rückblick (Beurteilung) – Ausblick (Ziele) – Entwicklung (Maßnahmen): die drei Teile des Jahresgesprächs.'}
  ]},
  {t:'Leistungs-Potenzial-Portfolio und Personaldurchsprache',h:'3.2 Instrumente und Methoden',pg:26,pdf:28,abb:[['Abb. 3.2 Portfoliofelder',27],['Beispiel: Arbeitsbogen Einschätzung nach Leistung und Potenzial',27]],b:[
    {p:'Viele Betriebe geben Führungskräften Formulare, mit denen sie ihre Mitarbeitenden nach Leistung und Potenzial einordnen. Daraus entsteht ein Portfolio; je nach Feld folgen unterschiedliche Entwicklungsaktivitäten. Die Feldnamen stammen aus der BCG-Matrix; in der Praxis gibt es andere Bezeichnungen (z. B. Dead Wood statt Poor Dogs, Workhorses statt Cash Cows).'},
    {svg:{w:520,h:290,body:'<g class="sk-t" text-anchor="middle"><path d="M80,250 H505" class="sk-l" marker-end="url(#ar)"/><path d="M80,250 V12" class="sk-l" marker-end="url(#ar)"/><rect x="88" y="20" width="200" height="105" class="sk-body"/><text x="188" y="45" class="sk-t acc">Question Marks</text><text x="188" y="65">Potenzial hoch,</text><text x="188" y="83">Leistung noch niedrig</text><text x="188" y="108">→ Projekte, Sonderaufgaben</text><rect x="298" y="20" width="200" height="105" class="sk-body"/><text x="398" y="45" class="sk-t acc">Stars</text><text x="398" y="65">Potenzial hoch,</text><text x="398" y="83">Leistung hoch</text><text x="398" y="108">→ Verantwortung übertragen</text><rect x="88" y="135" width="200" height="105" class="sk-body"/><text x="188" y="160" class="sk-t acc">Poor Dogs</text><text x="188" y="180">Potenzial niedrig,</text><text x="188" y="198">Leistung niedrig</text><text x="188" y="223">→ Einsatz/Ursachen prüfen</text><rect x="298" y="135" width="200" height="105" class="sk-body"/><text x="398" y="160" class="sk-t acc">Cash Cows</text><text x="398" y="180">Potenzial niedrig,</text><text x="398" y="198">Leistung hoch</text><text x="398" y="223">→ Anpassungsqualifizierung</text><text x="293" y="275" class="sk-t acc">Leistung</text><text x="110" y="270" text-anchor="start">niedrig</text><text x="470" y="270" text-anchor="start">hoch</text><text x="40" y="135" class="sk-t acc" transform="rotate(-90 40 135)">Potenzial</text></g>',cap:'Portfolio nach Leistung und Potenzial mit typischer Maßnahme'}},
    {tab:[['Feld','Beschreibung','Typische Maßnahme'],['Stars','hervorragende Leistung und überdurchschnittliches Potenzial','zeitnah Verantwortung übertragen (z. B. Führungsfunktion), Nachfolgeplanung'],['Question Marks','hohes Potenzial vermutet, Leistung überzeugt (noch) nicht – oft „Potenzialkandidaten“','praktische Tätigkeiten: Sonderaufgaben, Projekte, Nachwuchsprogramme; nicht nur Wissensvermittlung'],['Cash Cows','Leistungsträger mit überdurchschnittlicher Leistung, „genau richtig eingesetzt“, weiteres Potenzial nicht erkannt','Leistungsfähigkeit erhalten: Anpassungsqualifizierung an neue Rahmenbedingungen, Wertschätzung, Bindung'],['Poor Dogs','weder erwartete Leistung noch besonderes Potenzial','Ursachen klären (zu kurz in der Funktion? falsch eingesetzt?), abgestimmter Maßnahmenplan']]},
    {ul:['Personaldurchsprache: HR moderiert, die Portfolios der Führungskräfte werden bereichs- oder unternehmensweit übereinandergelegt und gemeinsam besprochen; bestätigende und abweichende Einschätzungen werden gesammelt.','Nutzen: Kalibrierung der Maßstäbe, einheitliches Verständnis, wer als Potenzialkandidat gilt; die so bestätigten Kandidaten werden von anderen Führungskräften eher akzeptiert.','In großen Betrieben werden oft nur die Potenzialkandidaten im Detail besprochen.','Einzelne Potenzialvermutungen sind anfällig für Beobachtungs- und Beurteilungsfehler (z. B. Halo-Effekt, Sympathie, Nikolaus-Effekt) → weitere Perspektiven einholen: AC, DC, Personaldurchsprache.']},
    {bsp:{t:'Beispiel: Portfolio einer Fertigungsgruppe mit 8 Personen',b:['Einordnung (Leistung/Potenzial je 1–6): A (5/5) Star, B (2/5) Question Mark, C (6/2) Cash Cow, D (5/2) Cash Cow, E (2/2) Poor Dog, F–H im Mittelfeld.','A: Übernahme der Schichtführung zum Jahreswechsel, vorher Führungsseminar.','B: erst 5 Monate im Betrieb, sehr lernfähig → Projekt „Rüstoptimierung“ als Bewährungsfeld.','C und D: wichtigste Fachkräfte; Schulung neue Messmaschine, Anerkennung als Paten für Neue.','E: Gespräch über Ursachen – stellt sich heraus: Sehschwäche bei Feinarbeiten, Einsatz an anderer Maschine; nach 3 Monaten neu einschätzen.','Danach Abgleich in der Personaldurchsprache mit den Meistern der Nachbarbereiche.']}},
    {falle:'Question Marks nicht mit Poor Dogs verwechseln: Question Marks haben hohes Potenzial bei (noch) schwacher Leistung. Die Prüfung verlangt oft je Feld Beschreibung und eine passende Maßnahme – Achsen beschriften!'}
  ]},
  {t:'Assessment-Center und Development-Center',h:'3.2 Instrumente und Methoden',pg:28,pdf:30,abb:[['Beispiel: Bewertungsprofil – Matching von Stellenprofil und Mitarbeiterkompetenzen',30]],b:[
    {p:'Ein Assessment-Center ist ein umfassendes eignungsdiagnostisches Verfahren: Mehrere Kandidaten durchlaufen nach festem Zeitplan Übungen und werden von mehreren Beobachtern hinsichtlich ihrer Eignung für bestimmte Positionen beurteilt. Beobachtet wird vor allem Leistung in definierten Übungen.'},
    {tab:[['Übung','Was gezeigt werden soll'],['Postkorb','Schriftstücke, Memos, Telefonnotizen nach Wichtigkeit und Dringlichkeit ordnen, effizient abarbeiten, in einen Kalender einplanen'],['Fallstudie, Fact-Finding','aus vielen relevanten und irrelevanten Informationen das Wesentliche erkennen, priorisieren, berechnen, mit Modellen aufbereiten'],['Präsentation (Selbst-, Partner-, Gruppen-, Themen-)','Inhalt, soziale Wirkung, Visualisierung, freie Rede'],['Rollenspiel','herausfordernde Situationen, z. B. Mitarbeitergespräche'],['Testreihen','Persönlichkeits-, Intelligenz-, Leistungs-, Belastungstests als wissenschaftliche Ergänzung'],['Interview','ergänzender Eindruck von der Person'],['Planspiel, Simulation','vorausschauendes, langfristiges Denken, Umgang mit komplexen Sachverhalten (oft computergestützt)'],['Gruppendiskussion','Führungsanspruch, Kommunikation, Sozialkompetenz – heute zurückhaltend genutzt, da Konkurrenz Kooperation hemmt'],['Arbeitsprobe','tatsächliches Arbeitsverhalten, je nach Beruf sehr verschieden']]},
    {svg:{w:520,h:190,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="10" width="150" height="50" class="sk-body"/><text x="85" y="31" class="sk-t acc">1 Profil</text><text x="85" y="49">Soll-Kompetenzen</text><rect x="185" y="10" width="150" height="50" class="sk-body"/><text x="260" y="31" class="sk-t acc">2 Übungen</text><text x="260" y="49">je Kompetenz ≥ 2</text><rect x="360" y="10" width="150" height="50" class="sk-body"/><text x="435" y="31" class="sk-t acc">3 Beobachten</text><text x="435" y="49">mehrere, unabhängig</text><rect x="360" y="100" width="150" height="50" class="sk-body"/><text x="435" y="121" class="sk-t acc">4 Konferenz</text><text x="435" y="139">Ist- vs. Soll-Profil</text><rect x="185" y="100" width="150" height="50" class="sk-body"/><text x="260" y="121" class="sk-t acc">5a AC</text><text x="260" y="139">Auswahlentscheidung</text><rect x="10" y="100" width="150" height="50" class="sk-body"/><text x="85" y="121" class="sk-t acc">5b DC</text><text x="85" y="139">Entwicklungsplan</text><path d="M160,35 H183" class="sk-l" marker-end="url(#ar)"/><path d="M335,35 H358" class="sk-l" marker-end="url(#ar)"/><path d="M435,60 V98" class="sk-l" marker-end="url(#ar)"/><path d="M360,125 H337" class="sk-f" marker-end="url(#ar)"/><path d="M435,150 V175 H85 V152" class="sk-f" marker-end="url(#ar)"/></g>',cap:'Ablauf eines AC bzw. DC'}},
    {ul:['Ziel jeder Übung: eine bestimmte Kompetenz beobachtbar machen; jede Kompetenz in mindestens zwei Übungen beobachten.','Mehrere Beobachter halten unabhängig ihre Einschätzung auf vorstrukturierten Bögen fest.','Beobachterkonferenz: Daten je Kandidat zusammentragen, als Profilwerte mit dem Soll-Profil der Stelle oder Rolle vergleichen.','Digitale Formate: softwaregestützte Planspiele, Postkorb und Fallstudien mit elektronischen Dokumenten.','Schwächen des AC: Darf man es wiederholen? Was passiert mit der Motivation guter Mitarbeitender, die „durchfallen“?']},
    {tab:[['Assessment-Center (AC)','Development-Center (DC)'],['Auswahl: der oder die Beste wird gesucht','Potenzial sichten: wo steht jemand?'],['Beurteilung durch Beobachter','zusätzlich Selbsteinschätzung und Peer-Feedback'],['es gibt „Verlierer“, gute Leute bleiben auf der Strecke','keine Verlierer, nur unterschiedliche Entwicklungsstände'],['Ergebnis: geeignet / nicht geeignet','Ergebnis: individueller Entwicklungsplan für jeden'],['auch: Auswahl-AC','auch: Potenzial-AC, Entwicklungs-AC']]},
    {bsp:{t:'Beispiel: Mini-DC für drei Nachwuchs-Schichtführer',b:['Anforderungsprofil: Planen und Organisieren, Kommunikation, Konfliktfähigkeit, Entscheiden unter Zeitdruck.','Übungen (1 Tag): Postkorb „Montagmorgen in der Fertigung“ (Krankmeldungen, Eilauftrag, Maschinenstörung), Rollenspiel „Mitarbeiter kommt wiederholt zu spät“, Kurzpräsentation „Mein Verbesserungsvorschlag“.','Beobachter: Meister, Personalreferentin, Produktionsleiter – getrennte Bögen, Skala 1–5.','Konferenz: Teilnehmer A zeigt im Postkorb Ø 4,3, im Rollenspiel 2,7 → Stärke Organisation, Lücke Gesprächsführung.','Ergebnis: individueller Plan – Seminar Gesprächsführung, danach zwei Kritikgespräche gemeinsam mit dem Meister führen.']}},
    {merke:'AC = Auswahl (Wer ist geeignet?), DC = Entwicklung (Wo steht jeder, was ist sein nächster Schritt?).'}
  ]},
  {t:'Qualifikation, Kompetenz und Schlüsselqualifikationen',h:'3.2 Instrumente und Methoden',pg:30,pdf:32,abb:[['Abb. 3.3 Handlungskompetenz und Schlüsselqualifikationen',31],['Abb. 3.4 Operationalisierung von Kompetenzen in Verhaltensanker',32]],b:[
    {p:'Kriterien für Potenzialeinschätzungen legt meist jedes Unternehmen selbst fest, auf Basis seiner Schlüsselkompetenzen. Allen Verfahren liegt also ein Anforderungsprofil zugrunde. Dafür muss man die Begriffe sauber trennen.'},
    {tab:[['Begriff','Bedeutung'],['Qualifikation','berufliches Fachwissen und Fertigkeiten nach formal definierten Kategorien, anerkannt durch Abschluss, Zertifikat oder Berechtigung (z. B. Ausbildung, anerkannte Weiterbildung)'],['Kompetenz','vorhandene oder geforderte Fähigkeit, Kenntnisse und Fertigkeiten anzuwenden (Können, Handlungsfähigkeit) – schließt Wissen, Erfahrung und Wollen (Motivation) ein; der weitere Begriff'],['Schlüsselqualifikation','überfachliche, erwerbbare Fähigkeiten, Einstellungen und Strategien, die beim Lösen von Problemen und beim Erwerb neuer Kompetenzen in vielen Bereichen helfen (Begriff aus den 1970er-Jahren)'],['Handlungskompetenz','Zusammenspiel von Fach-, Methoden-, Sozial- und personaler Kompetenz']]},
    {svg:{w:520,h:230,body:'<g class="sk-t" text-anchor="middle"><polygon points="10,55 260,8 510,55" class="sk-body"/><text x="260" y="45" class="sk-t acc">Handlungskompetenz</text><rect x="10" y="62" width="119" height="108" class="sk-body"/><text x="69" y="85" class="sk-t acc">Fach-</text><text x="69" y="103" class="sk-t acc">kompetenz</text><text x="69" y="135">Wissen,</text><text x="69" y="153">Fertigkeiten</text><rect x="137" y="62" width="119" height="108" class="sk-body"/><text x="196" y="85" class="sk-t acc">Methoden-</text><text x="196" y="103" class="sk-t acc">kompetenz</text><text x="196" y="135">planen,</text><text x="196" y="153">Probleme lösen</text><rect x="264" y="62" width="119" height="108" class="sk-body"/><text x="323" y="85" class="sk-t acc">Sozial-</text><text x="323" y="103" class="sk-t acc">kompetenz</text><text x="323" y="135">Team,</text><text x="323" y="153">Konflikte</text><rect x="391" y="62" width="119" height="108" class="sk-body"/><text x="450" y="85" class="sk-t acc">Personale</text><text x="450" y="103" class="sk-t acc">Kompetenz</text><text x="450" y="135">Werte,</text><text x="450" y="153">Lernwille</text><rect x="10" y="180" width="500" height="40" class="sk-body"/><text x="260" y="205">Methoden-, Sozial- und personale Kompetenz = überfachlich</text></g>',cap:'Vier Säulen der Handlungskompetenz'}},
    {tab:[['Bereich','Leitfrage','Beispiele'],['Fachkompetenz','Welche Fachfragen soll die Person beantworten können?','fachbezogene Kenntnisse, Fertigkeiten, Fähigkeiten'],['Methodenkompetenz','Welche Situationen muss sie wie angehen?','Projektmanagement, Moderation, Problemanalyse'],['Sozialkompetenz','Wie sollen Beziehungen gestaltet werden?','Kommunikation, Konflikt- und Teamfähigkeit'],['Personale Kompetenz','Welche Überzeugungen und Werte leiten ihr Handeln?','ethische Werte, Lernbereitschaft, realistisches Selbstbild']]},
    {ul:['Andere Einteilungen sind möglich (z. B. Führungskompetenz, interkulturelle Kompetenz).','Unspezifische Begriffe wie „Sozialkompetenz“ helfen in der Praxis nicht – sie müssen operationalisiert, also auf beobachtbare Verhaltensanker heruntergebrochen werden.','Beispiel „Führen mit Zielen“ (Methodenkompetenz Führungstechnik): stellt Verständnis für Ziele sicher, aktualisiert Ziele im Zeitverlauf, legt Verantwortung und Vollmachten klar fest, ermutigt zur Verantwortungsübernahme.','Mindestanforderungen festlegen; Stärken und Defizite gegen das Profil abgleichen; Lücken mit Qualifizierung und PE schließen.','Prüfungstypisch: Anforderungsprofil (z. B. Kundendienstmonteur) mit je mehreren persönlichen, fachlichen und sozialen Kriterien aufstellen und per Soll-Ist-Vergleich den Qualifizierungsbedarf ableiten.']},
    {bsp:{t:'Beispiel: Anforderungsprofil Servicetechniker Hydraulik (Außendienst)',b:['Fachlich: Hydraulikschaltpläne lesen, Fehlersuche mit Messgeräten, Grundlagen Elektrik/SPS, Montage- und Dichtungstechnik.','Methodisch: systematische Fehlersuche, Einsatz- und Reiseplanung, Servicebericht und Dokumentation.','Sozial: kundenorientiert kommunizieren, ruhig bei Konflikten, Zusammenarbeit mit Kundenpersonal.','Persönlich: selbstständig, belastbar, zuverlässig, kostenbewusst, ggf. Englisch.','Verhaltensanker „kundenorientiert“: erklärt dem Kunden Ursache und Lösung verständlich, meldet Termine verbindlich zurück, hinterlässt den Arbeitsplatz sauber.','Soll-Ist bei Kandidat: Fachlich 4/5, Elektrik 2/4 → Qualifizierungsbedarf SPS-Grundkurs und Begleitung von 5 Einsätzen mit einem erfahrenen Kollegen.']}},
    {falle:'Soll jemand den Meister vertreten, reichen Kompetenzen nicht – er braucht auch Befugnisse: Weisungsrecht, Unterschriftsberechtigung, Systemzugänge, Teilnahme an Führungsbesprechungen. Aufgabe, Kompetenz und Verantwortung müssen zusammenpassen.'}
  ]},
  {t:'Maßnahmen der Personalentwicklung im Überblick',h:'4.1 Maßnahmen der Personalentwicklung',pg:35,pdf:37,abb:[['Tab. 4.1 Entwicklungs- und Bildungsmaßnahmen',35]],b:[
    {p:'Der Meister braucht einen Überblick über die PE-Maßnahmen, wählt sie zielgerichtet aus (auch als Mischung von digitalem und Präsenzlernen), legt sie in Entwicklungsvereinbarungen fest und hält sie nach. Bildungsmaßnahmen vermitteln oft nur Wissen; kompetentes Handeln braucht zusätzlich Erfahrung und Motivation. Die Wahl zwischen Seminar, Lernen on the job, near the job oder Mischformen muss er begründen können.'},
    {svg:{w:520,h:165,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="10" width="122" height="90" class="sk-body"/><text x="71" y="32" class="sk-t acc">into the job</text><text x="71" y="56">Einarbeitung,</text><text x="71" y="76">Traineeprogramm</text><rect x="136" y="10" width="122" height="90" class="sk-body"/><text x="197" y="32" class="sk-t acc">on the job</text><text x="197" y="56">Unterweisung,</text><text x="197" y="76">Rotation, Projekt</text><rect x="262" y="10" width="122" height="90" class="sk-body"/><text x="323" y="32" class="sk-t acc">near the job</text><text x="323" y="56">Qualitätszirkel,</text><text x="323" y="76">Hospitation</text><rect x="388" y="10" width="122" height="90" class="sk-body"/><text x="449" y="32" class="sk-t acc">off the job</text><text x="449" y="56">Seminar, Studium,</text><text x="449" y="76">Fernlehrgang</text><path d="M250,125 H20" class="sk-f" marker-end="url(#ar)"/><path d="M270,125 H500" class="sk-f" marker-end="url(#ar)"/><text x="135" y="150">mehr Praxisnähe, leichter Transfer</text><text x="385" y="150">mehr Systematik, höhere Kosten</text></g>',cap:'Lernorte nach Nähe zum Arbeitsplatz'}},
    {tab:[['Maßnahme','Beschreibung','Eignung'],['Training/Learning on the job','geplantes, systematisches Lernen während und anhand der realen Arbeit; Fehler erlaubt; regelmäßiges qualifiziertes Feedback','praktische Lernerfahrung, vielseitig einsetzbar'],['Jobrotation, Job Enlargement, Job Enrichment','geplanter Arbeitsplatz- bzw. Aufgabenwechsel: gleiches Niveau (Enlargement) oder höheres Niveau (Enrichment)','Fachkompetenz erweitern, Flexibilität, soziale Kompetenz, bereichsübergreifendes Denken'],['Projektarbeit','Lernen an realen, neuartigen, befristeten Aufgaben des Unternehmens','vielseitig, je nach Schwerpunkt'],['Learning off the job','systematischer Erwerb außerhalb des Arbeitsplatzes: externe Seminare, Studiengänge, Trainings, Fernlehrgänge','Grundlagenwissen oder wenn die Nähe zum Arbeitsplatz eher stört'],['Planspiel/Simulation','modellhafte Bearbeitung eines praxisnahen Falls, Handlungsalternativen erproben und diskutieren','vernetztes Denken, Folgen von Entscheidungen'],['Seminar (extern)','externe Veranstaltung, meist Wissensvermittlung','Themen, für die sich intern nichts lohnt; Blick von außen; interne Vertraulichkeit'],['Training (intern)','auf interne Belange zugeschnittene Schulung mit Übungsschwerpunkt','einheitlich zu handhabende Themen, gleichartige Bedarfe'],['Coaching / Einzeltraining','individuelle Bearbeitung von Herausforderungen; Hilfe zur Selbsthilfe durch rückblickende Reflexion','Einzelpersonen, neue Aufgaben'],['Mentoring','erfahrenes Organisationsmitglied als Ansprechpartner für informelle Spielregeln, Türöffner, Feedbackgeber','Einarbeitung, Nachwuchskräfte'],['Interner Trainer, Tutoring, Patenschaft','Kollegen schulen Kollegen; Pate weist schrittweise ein','betriebsspezifisches Wissen sichern, wenn Erfahrene es weitergeben wollen'],['Moderation (z. B. Workshops)','schwierige Gruppensituationen und komplexe Sachverhalte steuern','Gruppenführung üben ohne Führungsfunktion (angehende Projekt-/Gruppenleitung)'],['E-Learning (CBT, WBT)','selbstständiges Lernen mit Datenträger bzw. über Inter-/Intranet','zeiteffizient bei Selbstdisziplin; braucht Zeit und Technik'],['Blended Learning','Selbstlernen (Literatur, E-Learning) + Präsenz (Seminar, on the job) zur Einübung','Wissen im eigenen Tempo, Anwendung mit Trainer, Coach, Führungskraft üben'],['Literaturstudium','Lernen aus Büchern und Zeitschriften','laufendes fachliches Update']]},
    {bsp:{t:'Beispiel: Passende Maßnahme für drei Fälle wählen',b:['Fall 1 – neue Messmaschine (3 Bediener): Herstellertraining inhouse an der eigenen Maschine (on the job) – Praxisnähe, einheitliches Vorgehen.','Fall 2 – angehender Gruppenleiter: Workshop-Moderation im KVP-Team übernehmen (near the job) + Seminar Führungsgrundlagen (off the job) + Mentor aus dem Nachbarbereich.','Fall 3 – neue Arbeitsschutzvorschrift für alle 40 MA: E-Learning-Modul mit Abschlusstest, anschließend 15 min Unterweisung am Arbeitsplatz (Blended Learning).','Begründung jeweils: Zweck, Zielgruppe, Kosten, Transfer.']}},
    {merke:'Erst den Zweck klären, dann die Maßnahme wählen. Training on the job: praxisnah, günstig, Erfolg direkt prüfbar, aber störanfällig. Training off the job: systematisch, didaktisch aufbereitet, Netzwerk, aber teuer und Transfer schwerer.'}
  ]},
  {t:'Lernen im Tagesgeschäft, Projekte und digitale Formen',h:'4.1 Maßnahmen der Personalentwicklung',pg:37,pdf:39,abb:[['Abb. 4.1 Traineeprogramm für angehende Projektleitungen',39],['Tab. 4.2 Entwicklungschancen von Mitarbeiterkompetenzen',40]],b:[
    {p:'Blended Learning verbindet Präsenzlernen und selbstgesteuertes Lernen (digital oder als Fernstudium) und nutzt, dass viele sich Wissen heute in kurzen Videos und auf Fachseiten holen.'},
    {tab:[['Digitales Lernen – Vorteile','Digitales Lernen – Nachteile'],['sofort verfügbar','eigene Fragen oft nicht abgedeckt'],['zeit- und ortsunabhängig','häufig keine Rückfragen, kein Austausch'],['beliebig wiederholbar','Qualität und Richtigkeit nicht immer prüfbar'],['geringe oder keine Kosten','manche Inhalte schwer auffindbar'],['Vor- und Nachbereitung von Präsenzinhalten','Technik nötig (Internet, Rechner)']]},
    {ul:['Die Nachteile lassen sich in Präsenzformaten ausgleichen: Übung im Seminar, Stellvertreteraufgabe in der Praxis (anders als Abwesenheitsvertretung ist hier der Hauptentscheider da).','Wissen aus Trainings wird erst durch Anwendung handlungsrelevant; bewährte Formen werden wiederentdeckt: Stellvertretung, Sonderprojekte, Infoaufenthalte, Hospitation (zuschauen, nicht mitarbeiten – anders als Praktikum), Jobrotation.','Größte Entwicklungserfahrungen stecken in Aufgaben, die: Erfolg und Scheitern ermöglichen; sichtbar einzeln verantwortlich machen; Arbeit mit vielen und schwierigen Gruppen verlangen (z. B. Betriebsrat, bereichsübergreifende Teams); unter Druck stattfinden (Termine, Reisen); Einfluss ohne direkte Weisungsbefugnis erfordern; Mehrdeutigkeit und Komplexität bringen; unter Beobachtung wichtiger Personen stehen; Teams aufbauen oder umbauen.','Mögliche Entwicklungsaufgaben: Arbeitsgruppe zu dringendem Problem begleiten, Veranstaltung planen, mit wichtigen Partnern verhandeln, Einstellungsverfahren begleiten, Systemeinführung begleiten, Umzug/Layout planen, mit dem Betriebsrat ein Thema bearbeiten, Aufenthalt in anderer Abteilung, Mitwirkung in Produktentwicklung, Auftaktveranstaltungen bei Veränderungen, festgefahrene Aufgaben übernehmen, Kostensenkung begleiten, Workshops moderieren, Wettbewerbsvergleiche.','Traineeprogramme: gemeinsames, strategisch relevantes Projekt + begleitende Seminare je Projektphase + Reflexion der Lernerfahrung; meist Methodenmix, teils mit externen Instituten.']},
    {tab:[['Entwicklungsziel','Fokus des Projekts'],['Analyse, Konzept, Präsentation, Umsetzungsstärke','reales übergreifendes Problem analysieren, Lösung erarbeiten, freigeben lassen und umsetzen'],['Spezialisierung, Aktualisierung des Fachwissens','Projekt aus eigenem Gebiet, neues Wissen im Jour fixe vorstellen'],['Fachwissen festigen, Sensibilität für Kulturunterschiede','eigenes Fachgebiet in anderem Bereich, Werk oder Land; Lernfokus auf Kultur'],['unternehmerische Fähigkeiten','strategisches Projekt mit kaufmännischer und Stakeholder-Verantwortung'],['erste Führungserfahrung','Projekt leiten, gezielt einzelne Führungsziele vereinbaren – weniger ist mehr']]},
    {ul:['Aufgabe der Führungskraft: vorher klar machen, was im Projekt gelernt werden soll.','Medienkompetenz als Lernziel: Wo und wie sucht man Informationen? Wie bewertet man Quellen? Wie verdichtet man und zieht Schlüsse? Was macht man damit? Dazu: Bewusstsein, was man von sich preisgibt, Umgangsformen bei digitalen Geräten, Selbstkontrolle bei der Nutzung.']},
    {bsp:{t:'Beispiel: Projekt als Lernfeld für einen jungen Techniker',b:['Projekt: Einführung von Kanban für Kleinteile in der Montage (3 Monate).','Vereinbarte Lernziele: 1) Ist-Analyse mit Daten (Analysefähigkeit), 2) Vorstellung vor Produktionsleitung (Präsentation), 3) Einbinden der Lagermitarbeiter ohne Weisungsbefugnis (Einfluss nehmen).','Begleitung: Meister als Ansprechpartner, wöchentlich 15 min Reflexion; Kurzseminar Präsentationstechnik vor dem Termin.','Auswertung: Projektziel (Fehlteile −40 %) erreicht; Lernziel 3 nur teilweise → nächstes Projekt mit Fokus Gesprächsführung.']}},
    {merke:'Lernen passiert vor allem bei herausfordernden Aufgaben im Tagesgeschäft – Seminare liefern das Wissen, die Praxis die Kompetenz.'}
  ]},
  {t:'Entwicklungsmaßnahmen nach Vereinbarung und Lernziele',h:'4.2 Entwicklungsmaßnahmen nach Vereinbarung',pg:41,pdf:43,abb:[['Beispiel: Musterformular – Inhalte eines Entwicklungsplans',41],['Tab. 4.3 Klassifizierung der Lernziele',43]],b:[
    {p:'Vereinbarte Maßnahmen werden schriftlich festgehalten und auf die Anforderungen des Arbeitsplatzes zugeschnitten. Neben Zeitfenster, Verantwortlichkeiten, Medien und Lernort spielen Lernzielstufe (Tiefe des Wissens) und Lernzielbereich eine Rolle. Je genauer die Vorgabe, desto exakter müssen Lernziele formuliert sein.'},
    {ol:['Ausgangssituation und Ziel: heutiger Stand (Interessen, Kenntnisse, Erfahrungen), Ziel bzw. angestrebte Funktion, Zwischenziele.','Maßnahmen: Lerninhalte off the job (Seminar, Fachliteratur, E-Learning), nötige Praxiserfahrungen, konkrete Aufgaben im oder neben dem Tagesgeschäft, Organisationseinheit, Projekte oder Sonderaufgaben.','Beteiligte: Was tut die Führungskraft? Wer unterstützt außerdem? Entsteht Mehraufwand, der mit Dritten (z. B. Familie) abgestimmt werden sollte?','Organisatorisches: Unterschriften (Mitarbeiter, Führungskraft, Entwicklungsverantwortliche), Termine der Statusgespräche, Kopie an die PE.']},
    {tab:[['Lernzielbereich','Bildlich','Beispiel Metall'],['kognitiv','Kopf – Kennen, Wissen','Toleranzangaben einer Zeichnung erklären'],['affektiv','Herz – Einstellungen, Werte','PSA auch bei kurzen Arbeiten konsequent tragen'],['psychomotorisch','Hand – manuelle Umsetzung','Kehlnaht in Zwangslage sauber schweißen']]},
    {svg:{w:520,h:230,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="180" width="100" height="40" class="sk-body"/><text x="60" y="198" class="sk-t acc">1 Wissen</text><text x="60" y="214">nennen</text><rect x="110" y="140" width="100" height="80" class="sk-body"/><text x="160" y="158" class="sk-t acc">2 Verstehen</text><text x="160" y="175">erklären</text><rect x="210" y="100" width="100" height="120" class="sk-body"/><text x="260" y="118" class="sk-t acc">3 Anwenden</text><text x="260" y="135">ausführen</text><rect x="310" y="60" width="100" height="160" class="sk-body"/><text x="360" y="78" class="sk-t acc">4 Analyse</text><text x="360" y="95">zerlegen</text><rect x="410" y="20" width="100" height="200" class="sk-body"/><text x="460" y="38" class="sk-t acc">5 Bewerten</text><text x="460" y="55">beurteilen</text><text x="20" y="40" text-anchor="start" class="sk-t acc">Kopf-Lernziele (kognitiv)</text><text x="20" y="62" text-anchor="start">Prüfung: meist Stufe 1–3</text><text x="20" y="84" text-anchor="start">genügen</text></g>',cap:'Lernzielstufen mit typischem Verb'}},
    {tab:[['Stufe','kognitiv (Verben)','psychomotorisch','affektiv'],['1','Wissen: nennen, aufzählen, berichten','Imitation: nachmachen, skizzieren','Beachten: aufnehmen, kontrollieren'],['2','Verstehen: erklären, unterscheiden, ordnen','Manipulation: fertigen, betätigen, steuern','Reagieren: beantworten'],['3','Anwenden: ausführen, ermitteln, benutzen','Präzision: exakt steuern, herstellen','Werten: anerkennen, helfen'],['4','Analyse: herausarbeiten, gegenüberstellen, nachweisen','Handlungsgliederung: Abläufe abstimmen, verknüpfen','Wertordnung: vergleichen, identifizieren'],['5','Synthese/Bewertung: planen, ableiten, berechnen, beurteilen','Naturalisation: automatisieren','Verhalten: überprüfen, durchsetzen, erfüllen']]},
    {ul:['Lernzieltaxonomien ordnen Lernziele vom Wissen zum tatsächlichen Können (ursprünglich sechs Stufen nach Bloom, Krathwohl, Masia; vom ISB München auf fünf Stufen verdichtet).','Für die Meisterpraxis reicht meist: Wissen – Verstehen – Anwenden. Die Detailtabelle muss in der Prüfung nicht wiedergegeben werden.','Inhalte können aus allen Kompetenzbereichen kommen: Fach (fachspezifische Kenntnisse), Methode (Arbeitsmethodik, Software), Sozial (Kommunikation, Zusammenarbeit), Persönlich (Selbst- und Stressmanagement).','Formular: oft reicht der Bogen des Jahresgesprächs oder der individuelle Entwicklungsplan, im einfachsten Fall eine formlose Notiz mit den wesentlichen Punkten.','Entscheidend ist nicht der Plan, sondern die Ernsthaftigkeit, mit der sich jemand kümmert, und die Nachhaltigkeit der Umsetzung.','In agilen Strukturen gewinnt kollegiales Feedback an Bedeutung; Entwicklung wird zunehmend von den Mitarbeitenden selbst gesteuert.']},
    {bsp:{t:'Beispiel: Entwicklungsplan für einen Einrichter',b:['Ausgangslage: Drehmaschineneinrichter, sicher an Steuerung A, keine Erfahrung mit Mehrspindlern.','Ziel: in 9 Monaten Mehrspindler-Drehautomaten selbstständig einrichten; Zwischenziel nach 3 Monaten: einfache Teile mit Unterstützung.','Off the job: Herstellerlehrgang 3 Tage (Lernziel Stufe 2: Aufbau und Kurvensteuerung erklären können).','On the job: 6 Wochen Tandem mit erfahrenem Einrichter (Stufe 3: einrichten), dann eigenverantwortlich mit Abnahme (Stufe 3–4: Fehler analysieren).','Beteiligte: Meister plant Tandemzeiten in der Schichtplanung; Mentor ist der Kollege Einrichter.','Statusgespräche: nach 3, 6, 9 Monaten; Unterschriften, Kopie an PE.']}},
    {merke:'Ein gutes Lernziel beschreibt beobachtbares Verhalten: „richtet die Spannvorrichtung ohne Hilfe in 20 min ein“ statt „kennt die Vorrichtung“.'}
  ]},
  {t:'Mitarbeitermotivation: klassische Modelle',h:'4.3 Mitarbeitermotivation',pg:43,pdf:45,abb:[['Abb. 4.2 Bedürfnispyramide nach Maslow',45]],b:[
    {p:'Von Motivation ist meist dann die Rede, wenn etwas stockt. Die Forschung bietet viele Ergebnisse; die klassischen Modelle geben bis heute brauchbare Hinweise für die Praxis.'},
    {ul:['Warum Menschen arbeiten (nach Vroom): Geld zur Erfüllung von Wünschen, sozialer Status durch die Art der Arbeit, Nichtarbeit ist sozial kaum akzeptiert, kreative Arbeit stärkt das Selbstbewusstsein, Arbeit ermöglicht soziale Kontakte.','Befriedigend wird Arbeit erlebt, wenn sie ganzheitlich (planen und ausführen), gestalterisch, produktiv (Aufwand und Ergebnis passen), interaktiv und sinnstiftend ist.']},
    {svg:{w:520,h:190,body:'<g class="sk-t" text-anchor="middle"><rect x="20" y="40" width="230" height="60" class="sk-body"/><text x="135" y="58" class="sk-t acc">Hygienefaktoren</text><text x="135" y="76">Entgelt, Sicherheit,</text><text x="135" y="94">Personalpolitik, Führung</text><rect x="270" y="40" width="230" height="60" class="sk-body"/><text x="385" y="58" class="sk-t acc">Motivatoren</text><text x="385" y="76">Inhalt, Verantwortung,</text><text x="385" y="94">Anerkennung, Aufstieg</text><path d="M20,130 H500" class="sk-l"/><path d="M260,120 V140" class="sk-l thick"/><path d="M30,115 H248" class="sk-f" marker-end="url(#ar)"/><path d="M272,115 H495" class="sk-f" marker-end="url(#ar)"/><text x="80" y="150">Unzufriedenheit</text><text x="260" y="158">neutral</text><text x="440" y="150">Zufriedenheit</text><text x="135" y="178">fehlen → unzufrieden</text><text x="385" y="178">vorhanden → motiviert</text></g>',cap:'Zwei-Faktoren-Theorie nach Herzberg'}},
    {tab:[['Herzberg','Wirkung','Beispiele'],['Hygienefaktoren','lösen Unzufriedenheit aus, wenn sie nicht ausreichend erfüllt sind; erzeugen selbst keine Motivation','Arbeitsplatzsicherheit, Entgelt, Personalpolitik, Einfluss auf das Privatleben, Führungsstil'],['Motivatoren','wirken leistungsfördernd – erst, wenn die Hygienefaktoren erfüllt sind','Arbeitsinhalt, Verantwortung, Aufstiegsperspektive, Anerkennung für Leistung, Entwicklungsmöglichkeiten']]},
    {ul:['Herzberg ist wegen Plausibilität und Anwendbarkeit in der Praxis sehr verbreitet. Einschränkung: Studien (House/Wigdor, 1967) zeigen, dass Motivatoren auch bei erfüllten Hygienefaktoren nicht zwingend zu mehr Leistung führen.']},
    {svg:{w:520,h:260,body:'<g class="sk-t" text-anchor="middle"><polygon points="260,10 300,58 220,58" class="fillacc"/><polygon points="220,58 300,58 340,106 180,106" class="sk-body"/><polygon points="180,106 340,106 380,154 140,154" class="sk-body"/><polygon points="140,154 380,154 420,202 100,202" class="sk-body"/><polygon points="100,202 420,202 460,250 60,250" class="sk-body"/><text x="260" y="87">Anerkennung</text><text x="260" y="135">Kontakt, Zugehörigkeit</text><text x="260" y="183">Sicherheit, Vorsorge</text><text x="260" y="231">Grundbedürfnisse (Essen, Schlaf)</text><path d="M290,40 H325" class="sk-c"/><text x="330" y="36" text-anchor="start" class="sk-t acc">Selbstverwirklichung</text><text x="330" y="54" text-anchor="start">Wachstumsmotiv</text><text x="480" y="140">Defizit-</text><text x="480" y="158">motive</text></g>',cap:'Bedürfnispyramide nach Maslow'}},
    {ul:['Maslow: fünf hierarchisch geordnete Motivgruppen – Grundbedürfnisse, Sicherheit, Kontakt/Zuwendung, Anerkennung/Selbstachtung, Selbstverwirklichung.','Die vier unteren sind Defizitmotive, Selbstverwirklichung ist ein Wachstumsmotiv.','Hierarchieprinzip: Die nächsthöhere Stufe wird erst aktiv, wenn die darunter weitgehend befriedigt ist; das niedrigste unbefriedigte Motiv ist das stärkste.','Kritik: empirisch kaum gestützt, stammt eher aus der Soziologie als aus der Motivationsforschung; in arbeitsteiliger Produktion ist Selbstverwirklichung schwer erreichbar – dennoch oft Grundlage der Praxis.']},
    {bsp:{t:'Beispiel: Motivation in der Lackiererei analysieren',b:['Situation: Hohe Krankmeldungen, Klagen über Hitze und unklare Schichtpläne; Lohn tariflich.','Herzberg-Sicht: Hitze und Schichtplanung sind Hygienefaktoren → zuerst beheben (Lüftung prüfen lassen, Schichtplan 4 Wochen im Voraus, mit Betriebsrat abgestimmt).','Danach Motivatoren: Lackierer übernehmen eigenverantwortlich die Farbtonprüfung (Verantwortung), Erfolge bei Reklamationsquote werden im Teamboard sichtbar (Anerkennung), ein Mitarbeiter wird zum Pulverbeschichtungs-Spezialisten qualifiziert (Entwicklung).','Maslow-Sicht: Sicherheit (verlässliche Planung) vor Anerkennung.']}},
    {falle:'Gehalt ist nach Herzberg ein Hygienefaktor: mehr Geld beseitigt Unzufriedenheit, motiviert aber nicht dauerhaft. Für Motivation sorgen Inhalt, Verantwortung und Anerkennung.'}
  ]},
  {t:'Psycho-Logik der Motivation und Praxis',h:'4.3.1 Die Psycho-Logik von Motivation – 4.3.2 … und was die Praxis dazu meint',pg:45,pdf:47,b:[
    {p:'Die populärsten Motivationsansätze beruhen auf der Verhaltenspsychologie: Verhalten wird durch seine Folgen gelernt.'},
    {svg:{w:520,h:240,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="95" width="110" height="50" class="sk-body"/><text x="65" y="116" class="sk-t acc">Verhalten</text><text x="65" y="134">des MA</text><rect x="170" y="20" width="150" height="44" class="sk-body"/><text x="245" y="38" class="sk-t acc">positive Folge</text><text x="245" y="56">Lob, Anerkennung</text><rect x="170" y="103" width="150" height="44" class="sk-body"/><text x="245" y="121" class="sk-t acc">negative Folge</text><text x="245" y="139">Kritik, Sanktion</text><rect x="170" y="186" width="150" height="44" class="sk-body"/><text x="245" y="204" class="sk-t acc">keine Folge</text><text x="245" y="222">nicht beachtet</text><rect x="370" y="20" width="140" height="44" class="sk-body"/><text x="440" y="38">wird wiederholt</text><text x="440" y="56">(Verstärkung)</text><rect x="370" y="103" width="140" height="44" class="sk-body"/><text x="440" y="121">wird vermieden</text><text x="440" y="139">(Vermeidung)</text><rect x="370" y="186" width="140" height="44" class="sk-body"/><text x="440" y="204">verschwindet</text><text x="440" y="222">(Demotivation)</text><path d="M120,112 L168,45" class="sk-l" marker-end="url(#ar)"/><path d="M120,120 H168" class="sk-l" marker-end="url(#ar)"/><path d="M120,128 L168,205" class="sk-l" marker-end="url(#ar)"/><path d="M320,42 H368" class="sk-f" marker-end="url(#ar)"/><path d="M320,125 H368" class="sk-f" marker-end="url(#ar)"/><path d="M320,208 H368" class="sk-f" marker-end="url(#ar)"/></g>',cap:'Lernen durch Konsequenzen – wichtig ist die zeitnahe Reaktion'}},
    {tab:[['Reaktion auf ein Verhalten','Wirkung'],['zeitnahe positive Anreize (Lob, Anerkennung, Belohnung)','Verhalten wird wahrscheinlicher wiederholt – extrinsische Motivation'],['zeitnahe Bestrafung oder Ankündigung von Sanktionen','Verhalten wird seltener – Vermeidungsstrategie'],['keine (zeitnahe) Reaktion','Verhalten wird ebenfalls seltener – Demotivation']]},
    {ul:['Commitment: Grundmotivation, wenn Mitarbeitende sich weitgehend mit Philosophie und Kultur des Unternehmens identifizieren und dazu bekennen.','Praxis: Theorie ist nicht immer sofort verwertbar; keine Führungskraft kann alle Einflussfaktoren steuern.','Ab etwa 20 Mitarbeitenden wäre individuelle Motivation jedes Einzelnen ein Vollzeitjob für Psychologen.','Trotzdem zeigen die Modelle, wo man im direkten Kontakt nach Beweggründen suchen kann, um die Lernbereitschaft gezielt zu unterstützen.']},
    {bsp:{t:'Beispiel: Verbesserungsvorschläge im Team fördern',b:['Problem: Seit Monaten kommen kaum Verbesserungsvorschläge – frühere Ideen blieben unbeantwortet (keine Reaktion → Verhalten erlischt).','Maßnahme 1: Jede Idee bekommt innerhalb von 48 h eine Rückmeldung des Meisters (zeitnahe Reaktion).','Maßnahme 2: Umgesetzte Ideen werden in der Schichtbesprechung mit Namen vorgestellt (Anerkennung).','Maßnahme 3: Abgelehnte Ideen werden begründet, nicht ignoriert.','Ergebnis nach einem Quartal: von 2 auf 14 Vorschläge, 6 umgesetzt.']}},
    {merke:'Wer auf gutes Verhalten nicht reagiert, verliert es. Rückmeldung zeitnah geben – positiv wie korrigierend.'}
  ]},
  {t:'Evaluation: Ebenen und deskriptive Daten',h:'5.1 Ebenen und Instrumente der Evaluierung – 5.1.1 Deskriptive Daten',pg:47,pdf:49,abb:[['Abb. 5.1 Sechs-Ebenen-Modell der ganzheitlichen Evaluation',48],['Tab. 5.1 Deskriptive Kennzahlen der Weiterbildung',49]],b:[
    {p:'Der Meister verantwortet nicht nur Qualifizierung, sondern auch die Kontrolle ihrer Ergebnisse. Controlling (to control = steuern) meint die Steuerung im Regelkreis; die Bewertung von Bildung heißt fachlich Evaluation – eine ganzheitliche, pädagogische (andragogische) und ökonomische Erfolgsbewertung. Grundlage: die vier Ebenen nach Kirkpatrick, ergänzt um deskriptive Daten und ROI zum Sechs-Ebenen-Modell.'},
    {svg:{w:520,h:260,body:'<g class="sk-t" text-anchor="middle"><text x="20" y="20" text-anchor="start">Aussagekraft und Aufwand steigen</text><path d="M20,30 H400" class="sk-f" marker-end="url(#ar)"/><rect x="10" y="190" width="82" height="40" class="sk-body"/><text x="51" y="208" class="sk-t acc">1</text><text x="51" y="225">Daten</text><rect x="92" y="160" width="82" height="70" class="sk-body"/><text x="133" y="178" class="sk-t acc">2</text><text x="133" y="195">Zufrie-</text><text x="133" y="212">denheit</text><rect x="174" y="130" width="82" height="100" class="sk-body"/><text x="215" y="148" class="sk-t acc">3</text><text x="215" y="165">Lernen</text><rect x="256" y="100" width="82" height="130" class="sk-body"/><text x="297" y="118" class="sk-t acc">4</text><text x="297" y="135" class="sk-t acc">Transfer</text><rect x="338" y="70" width="82" height="160" class="sk-body"/><text x="379" y="88" class="sk-t acc">5</text><text x="379" y="105">Output</text><rect x="420" y="40" width="82" height="190" class="sk-body"/><text x="461" y="58" class="sk-t acc">6</text><text x="461" y="75">ROI</text><text x="260" y="252" class="sk-t acc">Ebene 4 ist die Kernaufgabe des Meisters</text></g>',cap:'Sechs Ebenen der Weiterbildungs-Evaluation'}},
    {tab:[['Ebene','Leitfrage aus der Praxis','typische Instrumente'],['1 Deskriptive Daten','Was lief wann, für wen, in welchem Umfang, zu welchen Kosten?','Bildungsstatistik, Bildungsreport'],['2 Zufriedenheit','Wie zufrieden waren die Teilnehmenden?','Feedbackbogen, Blitzlicht, Stimmungsbarometer'],['3 Lernen','Was wurde gelernt?','Tests, Prüfung, Arbeitsprobe, Demonstration'],['4 Transfer','Was wurde konkret umgesetzt?','Transferplan, Nachgespräch, Beobachtung'],['5 Output','Werden Ziele besser, Aufgaben fehlerfreier erreicht?','Vorher-Nachher-Kennzahlen, Soll-Ist'],['6 ROI','Hat sich der Aufwand gelohnt?','ROI, Kosten-Nutzen-, Amortisationsrechnung']]},
    {ul:['Kennzahlen geben einen verdichteten Überblick; das meist informelle Gespräch über Zufriedenheit kostet wenig Zeit, ist aber die Grundlage, um Lernerfolgskontrolle und Transferunterstützung abzuschätzen – die wichtigste Aufgabe der Führungskraft.','Bildungsrendite und ROI sind eher HR-Aufgaben; einfache, schlanke Instrumente zur Dokumentation des Transfers sind trotzdem sinnvoll.','Deskriptive Daten (Inputgrößen): Thema, Art, Dauer, Teilnehmende nach Organisationseinheit und Hierarchie werden bei der Anmeldung erfasst und in Bildungshistorie oder Datenbanken gespeichert. Früher manuell, heute meist von den Teilnehmenden selbst eingegeben.','Software gleicht die Daten in Echtzeit mit Sollvorgaben ab und meldet Abweichungen (z. B. Budgetüberschreitung, fehlende Sicherheitsunterweisung → automatische Erinnerung, Empfehlung zum Gespräch an den Meister).','Bildungsreporte aus HR helfen für einen kostenstellenbezogenen Überblick.']},
    {tab:[['Kennzahlengruppe','Beispiele'],['Themen/Inhalte','Anteil einzelner Themen, Struktur fachlicher Veranstaltungen, Anteil Fach-, Methoden-, Sozial-, Individualkompetenz'],['Veranstaltungen/Zeit','Anzahl Veranstaltungen, Zeitaufwand, durchschnittliche Dauer, Weiterbildungszeit je MA, Stornos und Umbuchungen'],['Teilnehmende','Anzahl insgesamt und einfach gezählt, Anteil an der Stammbelegschaft, Alters- und Herkunftsstruktur, Anteil ohne bisherige Teilnahme'],['Methoden/Träger','Anteil interner/externer Trainer, aktiver/passiver Methoden, Selbststudium, technologiegestütztes Lernen'],['Kosten','Gesamtkosten, Kosten je Bereich, je MA, je Tag und Teilnehmer, Anteil an Personalkosten, Anteil ausgabewirksamer Kosten']]},
    {fx:{n:'Teilnahmequote',tex:'q_\\text{T} = \\frac{n_\\text{T}}{n_\\text{MA}} \\cdot 100\\,\\%',leg:[['q_\\text{T}','Teilnahmequote in %'],['n_\\text{T}','Teilnehmende, einfach gezählt (jede Person einmal)'],['n_\\text{MA}','Anzahl Mitarbeitende']],e:'Zeigt, wie breit Weiterbildung im Bereich streut.'}},
    {fx:{n:'Weiterbildungstage je Mitarbeitendem',tex:'\\bar{d} = \\frac{\\sum d_\\text{T}}{n_\\text{MA}}',leg:[['\\bar{d}','durchschnittliche Weiterbildungstage je MA'],['\\sum d_\\text{T}','Summe aller Teilnehmertage'],['n_\\text{MA}','Anzahl Mitarbeitende']]}},
    {fx:{n:'Weiterbildungskosten je Mitarbeitendem',tex:'k_\\text{MA} = \\frac{K_\\text{WB}}{n_\\text{MA}}',leg:[['k_\\text{MA}','Kosten je MA in €'],['K_\\text{WB}','gesamte Weiterbildungskosten in €'],['n_\\text{MA}','Anzahl Mitarbeitende']]}},
    {fx:{n:'Kosten je Teilnehmertag',tex:'k_\\text{TT} = \\frac{K_\\text{WB}}{\\sum d_\\text{T}}',leg:[['k_\\text{TT}','Kosten je Teilnehmertag in €'],['K_\\text{WB}','Weiterbildungskosten in €'],['\\sum d_\\text{T}','Summe der Teilnehmertage']]}},
    {fx:{n:'Anteil Weiterbildungskosten an den Personalkosten',tex:'a_\\text{WB} = \\frac{K_\\text{WB}}{K_\\text{P}} \\cdot 100\\,\\%',leg:[['a_\\text{WB}','Anteil in %'],['K_\\text{WB}','Weiterbildungskosten in €'],['K_\\text{P}','gesamte Personalkosten in €']]}},
    {bsp:{t:'Beispiel: Bildungskennzahlen eines Fertigungsbereichs',b:['Daten: 60 Mitarbeitende, 31 davon nahmen mindestens einmal teil, 96 Teilnehmertage, Weiterbildungskosten 38.400 €, Personalkosten des Bereichs 3,6 Mio. €.','Teilnahmequote = 31 ÷ 60 × 100 % = 51,7 %.','Weiterbildungstage je MA = 96 ÷ 60 = 1,6 Tage.','Kosten je MA = 38.400 € ÷ 60 = 640 €; Kosten je Teilnehmertag = 38.400 € ÷ 96 = 400 €.','Anteil an den Personalkosten = 38.400 € ÷ 3.600.000 € × 100 % = 1,07 %.','Interpretation: Fast die Hälfte hatte keine Weiterbildung – prüfen, ob gerade ältere oder angelernte MA fehlen (Altersstruktur auswerten).']}},
    {merke:'Controlling = Steuerung; Erfolgsbewertung von Bildung = Evaluation. Ebene 1 zählt nur den Input, sagt aber nichts über Wirkung.'}
  ]},
  {t:'Instrumente zur Zufriedenheitsmessung',h:'5.1.2 Instrumente zur Zufriedenheitsmessung',pg:50,pdf:52,abb:[['Beispiel: Stimmungsbarometer',50],['Beispiel: Feedbackbogen',50]],b:[
    {p:'Zufriedenheit zu messen ist vertrautes Terrain. Trainer nutzen im Prozess das Stimmungsbarometer oder das Blitzlicht am Tagesende; am Ende steht meist der Feedbackbogen – das am weitesten verbreitete Evaluationsinstrument.'},
    {tab:[['Instrument','Vorgehen','Nutzen'],['Stimmungsbarometer','Teilnehmende kleben einen Punkt auf einer Skala (z. B. Smileys) zu einer Frage','schnelles Stimmungsbild während des Seminars'],['Blitzlicht','jeder sagt reihum einen Satz zum Tag','offene Rückmeldung, Probleme früh erkennen'],['Feedbackbogen','standardisierte Fragen mit Skala (trifft voll zu … gar nicht zu) + Freitext; oft per QR-Code am Smartphone','einfache Auswertung, Ergebnisse in Echtzeit'],['Gespräch mit dem Meister','informell nach der Rückkehr: Lernausbeute, Umsetzungsvorhaben, Unterstützungsbedarf','Grundlage für Transfer']]},
    {ul:['Typische Bereiche eines Feedbackbogens: Gesamturteil; Organisation (Einladung, Infomaterial, Räume, Zeitpunkt und Dauer, Teilnehmerzusammensetzung); Inhalte (Struktur, Verständlichkeit, Praxisbezug); Trainer (Fachkompetenz, Praxisbeispiele, Medien, Wechsel der Arbeitsformen, Klima); sonstige Anregungen.','Angaben vertraulich behandeln; Name freiwillig.','Die Personalabteilung meldet meist die durchschnittliche Zufriedenheit mit einem Seminar.','Zufriedenheit ist kein Lernerfolg – ein unterhaltsamer Trainer garantiert keinen Transfer.']},
    {fx:{n:'Mittelwert einer Bewertungsfrage',tex:'\\bar{x} = \\frac{\\sum (x_i \\cdot n_i)}{\\sum n_i}',leg:[['\\bar{x}','Mittelwert der Bewertung'],['x_i','Skalenwert (z. B. 1 = trifft voll zu … 4 = trifft gar nicht zu)'],['n_i','Anzahl Nennungen dieses Skalenwerts'],['\\sum n_i','Anzahl Antworten']],e:'Bei dieser Skala gilt: je kleiner, desto besser.'}},
    {fx:{n:'Zustimmungsquote',tex:'q_\\text{Z} = \\frac{n_1 + n_2}{\\sum n_i} \\cdot 100\\,\\%',leg:[['q_\\text{Z}','Zustimmung in %'],['n_1, n_2','Nennungen „trifft voll zu“ und „trifft eher zu“'],['\\sum n_i','Anzahl Antworten']]}},
    {bsp:{t:'Beispiel: Feedback zur Hydraulikschulung auswerten',b:['12 Teilnehmende bewerten „Die Inhalte haben Bezug zu meiner Praxis“: 5× „trifft voll zu“ (1), 4× „eher zu“ (2), 2× „eher nicht“ (3), 1× „gar nicht“ (4).','Mittelwert = (5×1 + 4×2 + 2×3 + 1×4) ÷ 12 = 23 ÷ 12 = 1,92.','Zustimmung (Werte 1 und 2) = 9 ÷ 12 = 75 %.','Interpretation: überwiegend praxisnah; die drei kritischen Stimmen kommen aus der Instandhaltung → Meister fragt nach, ob Themen wie Fehlersuche an Proportionalventilen fehlten, und meldet das an den Anbieter.']}},
    {merke:'Die Zufriedenheitsfrage ist schnell gestellt und öffnet das Gespräch über Lernen und Umsetzung – sie ersetzt es aber nicht.'}
  ]},
  {t:'Evaluation des Lernerfolgs',h:'5.1.3 Evaluation des Lernerfolgs',pg:52,pdf:54,b:[
    {p:'Auf dieser Ebene wird geprüft, ob und wie viel gelernt wurde. Für Wissen eignen sich Tests und Prüfungen, für Fertigkeiten Arbeitsprobe und Demonstration; Einstellungen lassen sich nur mit psychologischen Verfahren messen – praktisch wird beobachtbares Verhalten bewertet.'},
    {tab:[['Lernziel','Instrument','Beispiel'],['Wissen','Test (z. B. digitaler Multiple Choice), Punkte- oder Notendurchschnitt','Test zur Gefahrstoffkennzeichnung'],['Fertigkeit','Arbeitsprobe, Demonstration','Schweißprobe, Einrichten einer Maschine vorführen'],['formale Berechtigung','Abschlussprüfung, Zertifikat, Fahrerlaubnis','Staplerschein, Kranschein, Gefahrgutschulung'],['Einstellung','Beobachtung des Verhaltens (psychologische Verfahren selten)','PSA wird ohne Erinnerung getragen']]},
    {ul:['Multiple-Choice-Tests erlauben schnelle, objektive Beurteilung auch über große Stoffgebiete.','Tests erinnern viele an Schule – die Dokumentation in Zeugnis, Teilnahmebescheinigung oder Zertifikat wird aber meist begrüßt.','Der Meister sollte sicherstellen, dass sich Mitarbeitende nach der Maßnahme sicher fühlen: Haben sie das nötige Wissen? Konnten sie die Anwendung erproben? Wo bestehen Unsicherheiten?','Ansprechperson als Backup für die ersten Schritte verabreden – evtl. der Meister selbst.']},
    {fx:{n:'Lernzuwachs',tex:'\\Delta L = L_\\text{nach} - L_\\text{vor}',leg:[['\\Delta L','Lernzuwachs in Prozentpunkten'],['L_\\text{nach}','Ergebnis Nachtest in %'],['L_\\text{vor}','Ergebnis Vortest in %']]}},
    {fx:{n:'Relativer Lerngewinn',tex:'g = \\frac{L_\\text{nach} - L_\\text{vor}}{100\\,\\% - L_\\text{vor}} \\cdot 100\\,\\%',leg:[['g','erreichter Anteil des möglichen Zuwachses in %'],['L_\\text{nach}','Nachtest in %'],['L_\\text{vor}','Vortest in %']]}},
    {bsp:{t:'Beispiel: Lernerfolg einer Messtechnik-Schulung',b:['Vortest vor der Schulung: Ø 45 % richtige Antworten (Toleranzen, Form- und Lagetoleranzen, Messmittelwahl).','Nachtest nach 2 Tagen Schulung: Ø 85 %.','Lernzuwachs = 85 % − 45 % = 40 Prozentpunkte.','Relativer Lerngewinn = 40 ÷ (100 − 45) × 100 % = 72,7 % des möglichen Zuwachses.','Zusätzlich Arbeitsprobe: Jeder misst ein Prüfteil mit Messschieber, Bügelmessschraube und Höhenmessgerät; Abweichung zur Messmaschine max. 0,02 mm = bestanden.','Interpretation: Wissen gut aufgebaut; ob im Alltag richtig gemessen wird, zeigt erst die Transferkontrolle.']}},
    {merke:'Tests messen Wissen, nicht die Anwendung. Fertigkeiten durch Arbeitsprobe oder Demonstration prüfen.'}
  ]},
  {t:'Unterstützung des Transfers',h:'5.1.4 Unterstützung des Transfers',pg:53,pdf:55,b:[
    {p:'Für den Betrieb zählt, ob die Arbeit mit dem Gelernten besser gelingt – nicht das Zertifikat. Das Transferproblem entsteht durch die Trennung von Lernfeld und Arbeitsfeld. Am besten ist es, organisiertes Lernen und Arbeiten zu verbinden: Mitarbeitende lösen mit Trainer oder Coach konkrete Probleme an ihrem Arbeitsplatz (spart Zeit, hoher Lerneffekt).'},
    {svg:{w:520,h:215,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="10" width="160" height="150" class="sk-body"/><text x="90" y="32" class="sk-t acc">vorher</text><text x="90" y="60">Ziel klären</text><text x="90" y="82">Erwartungen</text><text x="90" y="104">Praxisfragen</text><text x="90" y="126">Freistellung</text><rect x="180" y="10" width="160" height="150" class="sk-body"/><text x="260" y="32" class="sk-t acc">während</text><text x="260" y="60">lernen, üben</text><text x="260" y="82">Transferplan</text><text x="260" y="104">Fragen sammeln</text><text x="260" y="126">Vertretung regeln</text><rect x="350" y="10" width="160" height="150" class="sk-body"/><text x="430" y="32" class="sk-t acc">nachher</text><text x="430" y="60">Nachgespräch</text><text x="430" y="82">Aufgabe geben</text><text x="430" y="104">Rückmeldung</text><text x="430" y="126">Bilanz ziehen</text><path d="M20,185 H500" class="sk-f" marker-end="url(#ar)"/><text x="260" y="207">Führungskraft begleitet durchgehend</text></g>',cap:'Transfersicherung vor, während und nach der Maßnahme'}},
    {ul:['Klassische Transferinstrumente: Transferplan, „Brief an sich selbst“, Vertrag mit sich selbst.','Inhalte eines Transferplans: Welche drei Ideen nehme ich mit, was spricht mich daran an? Welchen Nutzen, welche konkreten Ziele will ich erreichen? Wann fange ich an? Was tue ich, damit es klappt? Wer oder was kann mich unterstützen? Wann ziehe ich mit der Führungskraft (Zwischen-)Bilanz?','Seminarbericht im Kollegenkreis: Wer allein auf eine Schulung geht, erhält vorab eine Protokollvorlage und berichtet danach in einer Besprechung (Zeit und Inhalt mit der Führungskraft abstimmen).','Inhalte der Protokollvorlage: Thema, Inhalt, Ablauf; Bestätigung bewährter Praxis; Highlights (ggf. Unterlagen verteilen); möglicher Nutzen; Stellungnahmen der Kollegen; Vereinbarung zum weiteren Vorgehen (Maßnahmenplan).','Der Meister schafft Rahmen und Priorität für den Transfer – gerade wenn das Tagesgeschäft hektisch wird.']},
    {bsp:{t:'Beispiel: Transfer nach einem SPS-Grundkurs',b:['Vorgespräch: Ziel ist, Störungen an der Verkettungsanlage selbst zu finden, statt den Elektriker zu rufen; Mitarbeiter notiert 3 typische Störungen als Praxisfragen für den Kurs.','Nach dem Kurs: Transferplan – ab Montag bei jeder Störung zuerst Diagnose am Panel; Ansprechpartner ist der Betriebselektriker; Bilanz in 4 Wochen.','Seminarbericht in der Schichtbesprechung (10 min) mit Kurzanleitung „Fehlerspeicher lesen“.','Bilanz nach 4 Wochen: 7 von 10 Störungen selbst behoben, mittlere Stillstandszeit von 40 auf 18 min.']}},
    {merke:'Transfer ist Führungsaufgabe: Transferpläne besprechen und regelmäßig Interesse an Umsetzungsvorhaben und -erfolgen zeigen.'}
  ]},
  {t:'Bemessung des Geschäftserfolgs (Output)',h:'5.1.5 Bemessung des Geschäftserfolgs (Output)',pg:54,pdf:56,abb:[['Tab. 5.2 Mögliche quantitative Output-Dimensionen',54],['Tab. 5.3 Mögliche qualitative Output-Dimensionen',54]],b:[
    {p:'Auf der Ebene Output wird das Ausmaß eines erzielten oder verbesserten Ergebnisses über Zielvereinbarungen, Soll-Ist-Vergleiche und Gap-Analysen (z. B. anhand der Stellenprofile) ermittelt – am besten als Vorher-Nachher-Messung.'},
    {tab:[['Quantitativ: Bereich','Kennzahlen'],['Produktion','Arbeitsproduktivität, Umsatz und Verkaufszahlen, abgeschlossene Vorgänge'],['Zeit','Entwicklungs- und Durchlaufzeiten, Stillstandszeiten, termingerechte Projekte'],['Qualität','Ausschuss- und Fehlerquoten, Reklamations- und Stornoquote'],['Kosten','Produktionskosten, Stückkosten, Materialverbrauch, Budgetabweichungen']]},
    {tab:[['Qualitativ: Bereich','Kennzahlen'],['Arbeitsverhalten','Unfälle, Krankenstand, Abwesenheiten'],['Initiative','Patentanmeldungen, Verbesserungsvorschläge, umgesetzte Ideen'],['Arbeitsklima','Arbeitszufriedenheit, Beschwerden, Fluktuation'],['Entwicklung','Beförderungen, Bildungsmaßnahmen, Lohnerhöhungen'],['Unternehmenskultur','Kommunikation und Information, Motivation und Leistungsbereitschaft, Führung und Kooperation']]},
    {ul:['Vor der Buchung mit der PE-Abteilung klären, was eine Maßnahme leisten kann – unterschiedliche Erwartungen werden früh sichtbar.','Mit dem Mitarbeitenden schriftlich festhalten, welches Ziel und welche Ergebniserwartung mit der Schulung verbunden sind.','Vorbereitendes Gespräch lenkt die Aufmerksamkeit auf wichtige Inhalte; Nachgespräch zu Zufriedenheit und Lernerfolg fördert die Umsetzung.','Veränderungen haben meist mehrere Ursachen → von einem plausiblen Beitrag sprechen, nicht von Ursache und Wirkung.']},
    {fx:{n:'Veränderung einer Kennzahl in Prozentpunkten',tex:'\\Delta q = q_\\text{nach} - q_\\text{vor}',leg:[['\\Delta q','Veränderung in Prozentpunkten'],['q_\\text{vor}','Quote vor der Maßnahme in %'],['q_\\text{nach}','Quote nach der Maßnahme in %']]}},
    {fx:{n:'Relative Verbesserung',tex:'r = \\frac{q_\\text{vor} - q_\\text{nach}}{q_\\text{vor}} \\cdot 100\\,\\%',leg:[['r','relative Verringerung (z. B. Reklamationen) in %'],['q_\\text{vor}','Quote vorher'],['q_\\text{nach}','Quote nachher']],e:'Plausibler Beitrag, kein Ursachenbeweis.'}},
    {bsp:{t:'Beispiel: Output nach einer Schulung zur Prüfplanung',b:['Maßnahme: 6 Mitarbeitende der Endkontrolle werden in Prüfplanung und Messsystemanalyse geschult.','Kennzahl vorher (Quartal davor): Reklamationsquote 1,8 % der ausgelieferten Teile; nachher (Quartal danach): 1,1 %.','Veränderung = 1,1 % − 1,8 % = −0,7 Prozentpunkte; relativ = 0,7 ÷ 1,8 × 100 % = 38,9 % weniger Reklamationen.','Weitere Einflüsse prüfen: Gab es neues Rohmaterial, einen neuen Lieferanten, geänderte Kundenanforderungen?','Bewertung: plausibler Beitrag der Schulung, kein Beweis – trotzdem im Bericht an die Produktionsleitung nennen.']}},
    {falle:'„Seit der Schulung ist der Ausschuss gesunken, also wirkt die Schulung“ – das ist ein Kausalschluss, den die Daten meist nicht tragen. Prüfer erwarten den Hinweis auf weitere Einflussfaktoren.'}
  ]},
  {t:'Berechnung des Return on Investment',h:'5.1.6 Berechnung des Return on Investment (ROI)',pg:56,pdf:58,abb:[['Abb. 5.2 Ebenen der Evaluation betrieblicher Bildungsmaßnahmen',56]],b:[
    {p:'Der ROI stellt Ergebnis und eingesetztes Kapital gegenüber und soll zeigen, ob sich eine Investition in eine Bildungsmaßnahme lohnt. Einen eindeutigen Ursache-Wirkungs-Beweis liefert er nicht. Alternativen sind Kosten-Nutzen-Rechnung, Amortisationsrechnung und Vergleichsrechnungen. Solche Berechnungen führen meist Spezialisten aus HR durch – der Meister liefert aber die Zahlen und sollte die Logik verstehen.'},
    {fx:{n:'Kosten einer Bildungsmaßnahme',tex:'K = K_\\text{G} + t_\\text{A} \\cdot k_\\text{h} + K_\\text{R} + K_\\text{V}',leg:[['K','Gesamtkosten in €'],['K_\\text{G}','Seminargebühren in €'],['t_\\text{A}','Ausfallzeit in h (Teilnehmende × Tage × h/Tag)'],['k_\\text{h}','Stundensatz in €/h'],['K_\\text{R}','Reise- und Unterkunftskosten in €'],['K_\\text{V}','ggf. Vertretungskosten in €']],e:'Die Ausfallzeit ist oft der größte Posten.'}},
    {fx:{n:'Bildungs-ROI',tex:'\\text{ROI} = \\frac{N - K}{K} \\cdot 100\\,\\%',leg:[['\\text{ROI}','Return on Investment in %'],['N','monetärer Nutzen im Betrachtungszeitraum in €'],['K','Kosten der Maßnahme in €']],e:'Positiv: Nutzen übersteigt die Kosten. Annahmen offenlegen.'}},
    {fx:{n:'Amortisationszeit',tex:'t_\\text{A} = \\frac{K}{N_\\text{a}} \\cdot 12',leg:[['t_\\text{A}','Amortisationszeit in Monaten'],['K','Kosten der Maßnahme in €'],['N_\\text{a}','Nutzen je Jahr in €/Jahr'],['12','Monate je Jahr']],e:'Ohne Faktor 12 ergibt sich die Zeit in Jahren.'}},
    {svg:{w:520,h:280,body:'<g class="sk-t" text-anchor="middle"><path d="M60,230 H495" class="sk-l" marker-end="url(#ar)"/><path d="M60,230 V15" class="sk-l" marker-end="url(#ar)"/><path d="M60,150.5 H480" class="sk-l"/><path d="M60,230 L480,57.7" class="sk-f"/><path d="M254,150.5 V230" class="sk-c"/><path d="M165,230 V236 M270,230 V236 M375,230 V236 M480,230 V236 M54,158.6 H60 M54,87.1 H60" class="sk-l"/><text x="60" y="250">0</text><text x="165" y="250">3</text><text x="270" y="250">6</text><text x="375" y="250">9</text><text x="480" y="250">12</text><text x="270" y="272">Monate</text><text x="50" y="235" text-anchor="end">0</text><text x="50" y="163" text-anchor="end">5.000</text><text x="50" y="92" text-anchor="end">10.000</text><text x="30" y="20">€</text><path d="M80,32 H110" class="sk-f"/><text x="118" y="37" text-anchor="start">kumulierter Nutzen</text><path d="M80,54 H110" class="sk-l"/><text x="118" y="59" text-anchor="start">Kosten 5.564 €</text><text x="345" y="200" class="sk-t acc">Amortisation ≈ 5,5 Monate</text></g>',cap:'Amortisation einer Schulung: kumulierter Nutzen überholt die Kosten'}},
    {bsp:{t:'Beispiel: ROI einer Rüst- und Prozessschulung',b:['Maßnahme: 2 Einrichter, 3-tägiges Seminar „Rüstzeitreduzierung und Prozessstabilität“.','Kosten: Gebühren 2 × 1.450 € = 2.900 €; Ausfallzeit 2 × 3 Tage × 8 h × 48 €/h = 2.304 €; Reise 2 × 180 € = 360 €; gesamt 5.564 €.','Nutzen pro Jahr: Ausschuss sinkt bei 40.000 Teilen von 3,2 % auf 2,0 % → 480 Teile × 9,50 € = 4.560 €; Rüstzeit −15 min bei 400 Rüstvorgängen = 100 h × 75 €/h Maschinenstundensatz = 7.500 €; Summe 12.060 €.','ROI = (12.060 € − 5.564 €) ÷ 5.564 € × 100 = 116,8 % im ersten Jahr.','Amortisationszeit = 5.564 € ÷ 12.060 €/Jahr × 12 = 5,5 Monate.','Interpretation: Die Schulung rechnet sich deutlich; Annahmen (Stückzahl, Stundensatz, Anteil der Schulung an der Verbesserung) offenlegen.']}},
    {tab:[['Ebene','Was der Meister tut'],['1 Daten','Bildungsreport anfordern, Teilnahme im Blick halten'],['2 Zufriedenheit','nach der Rückkehr kurz nachfragen'],['3 Lernerfolg','Sicherheit in der Anwendung erfragen, Arbeitsprobe'],['4 Transfer','wichtigster Teil: Rahmen schaffen, Priorität halten, Feedback'],['5 Output','Kennzahlen vorher/nachher, Plausibilität statt Kausalität'],['6 ROI','Zahlen liefern, Berechnung meist HR']]},
    {merke:'Ergebnisse der Evaluation nicht nur in der Wirksamkeitskontrolle, sondern auch im Mitarbeiterjahresgespräch (Beurteilung, Förderung) wieder aufgreifen.'}
  ]},
  {t:'Wirksamkeit und Nachhaltigkeit von Umsetzungsmaßnahmen',h:'5.2 Wirksamkeit und Nachhaltigkeit betrieblicher Umsetzungsmaßnahmen',pg:57,pdf:59,abb:[['Beispiel: Wirksamkeitskontrolle von Qualifizierungs- und Entwicklungsmaßnahmen',58]],b:[
    {p:'Maßnahmen zu vereinbaren ist leicht – ob sie verfolgt werden und wirken, muss geprüft werden. Bewährt hat sich: zeitnah eine Durchführungskontrolle, danach in regelmäßigen Abständen Wirksamkeitskontrollen, meist durch Beobachtung bei Arbeitsplatzbegehungen und Befragung der Handelnden.'},
    {svg:{w:520,h:225,body:'<g class="sk-t" text-anchor="middle"><polygon points="65,20 117,60 65,100 13,60" class="sk-body"/><text x="65" y="65">bekannt?</text><polygon points="190,20 242,60 190,100 138,60" class="sk-body"/><text x="190" y="65">verstanden?</text><polygon points="315,20 367,60 315,100 263,60" class="sk-body"/><text x="315" y="65">wirksam?</text><polygon points="440,20 492,60 440,100 388,60" class="sk-body"/><text x="440" y="65">eingehalten?</text><path d="M117,60 H136" class="sk-l" marker-end="url(#ar)"/><path d="M242,60 H261" class="sk-l" marker-end="url(#ar)"/><path d="M367,60 H386" class="sk-l" marker-end="url(#ar)"/><text x="126" y="50">ja</text><text x="251" y="50">ja</text><text x="376" y="50">ja</text><path d="M65,100 V138" class="sk-f" marker-end="url(#ar)"/><path d="M190,100 V138" class="sk-f" marker-end="url(#ar)"/><path d="M315,100 V138" class="sk-f" marker-end="url(#ar)"/><path d="M440,100 V138" class="sk-f" marker-end="url(#ar)"/><text x="80" y="124" text-anchor="start">nein</text><text x="205" y="124" text-anchor="start">nein</text><text x="330" y="124" text-anchor="start">nein</text><text x="455" y="124" text-anchor="start">nein</text><rect x="10" y="140" width="245" height="44" class="sk-body"/><text x="132" y="158" class="sk-t acc">unterweisen</text><text x="132" y="176">erklären und begründen</text><rect x="263" y="140" width="110" height="44" class="sk-body"/><text x="318" y="158" class="sk-t acc">Regel ändern</text><text x="318" y="176">Workshop</text><rect x="388" y="140" width="122" height="44" class="sk-body"/><text x="449" y="158" class="sk-t acc">Gespräch</text><text x="449" y="176">Ursache klären</text><text x="260" y="212" class="sk-t acc">viermal ja → Maßnahme wirksam und nachhaltig</text></g>',cap:'Durchführungskontrolle am Beispiel einer Arbeitsschutzregel'}},
    {ol:['Ist die Regelung bekannt (Arbeitsanweisung, Aushang, Infoposter, Schulung)?','Ist sie verständlich – können Mitarbeitende sie begründen?','Löst die Regelung das Problem?','Wird immer so gehandelt? Gibt es Ausnahmen?']},
    {ul:['Nicht bekannt oder nicht verstanden → umgehend unterweisen.','Wiederkehrende Abweichungen → Workshop, Qualitätszirkel oder Gespräch zwischen Mitarbeitenden und Führungskraft zur Lösungssuche – das verbessert die Nachhaltigkeit.','Mit Übertragung einer Aufgabe und Kontrollen in (un)regelmäßigen Abständen sowie Befragung der Beteiligten lässt sich die Nachhaltigkeit von Vereinbarungen prüfen.','PE-Controlling im Beurteilungs- und Fördergespräch: Sind die nötigen Qualifikationen erworben? Ist eine Kompetenzlücke geschlossen (auch Erfahrungszuwachs)? Wurde Neues erfolgreich angewendet? Kann die Person ihre Aufgaben jetzt besser erfüllen?','Hilfsmittel: individuelle Transferplanungen (auch per App), Änderungen in Quali-Matrix oder Kompetenzprofil.','Beurteilungen ziehen meist PE-Maßnahmen nach sich; wirken diese, lässt sich plausibel ein Beitrag zur besseren Aufgabenerfüllung ableiten.','Bei identischen Maßnahmen für größere Gruppen sind Rückschlüsse auf die Wirksamkeit möglich – Rahmenbedingungen sorgfältig mitbetrachten.','Prozessuale Nachverfolgung über die Zeit (aufwendig, aber nachhaltig) in drei Schritten: Qualifikation vermittelt → Kompetenz durch Üben entwickelt → in der Praxis erfolgreich angewendet; je Schritt Gesprächstermin, Bewertung und Handlungsbedarf. Auch nutzbar als Wirksamkeitsnachweis im QM-System (z. B. ISO 9001: Kompetenz, Bewertung der Wirksamkeit).']},
    {bsp:{t:'Beispiel: Wirksamkeitskontrolle nach Herstellerschulung am Bearbeitungszentrum',b:['Schritt 1 Qualifikation (Termin direkt nach Schulung): Teilnahmebescheinigung liegt vor, Kurztest zum Werkzeugwechsel bestanden → trifft zu.','Schritt 2 Kompetenz (nach 3 Wochen): Mitarbeiter hat unter Aufsicht 5 Rüstvorgänge durchgeführt, Feedback vom Einrichter → trifft eher zu, Handlungsbedarf: Nullpunktverschiebung üben.','Schritt 3 Transfer (nach 3 Monaten): selbstständiger Einsatz in 2 Schichten/Woche, Vorgabezeiten eingehalten, keine Kollision → trifft voll zu.','Dokumentation: Quali-Matrix auf „beherrscht in Qualität und Zeit“ setzen; Ablage für das QM-Audit.']}},
    {merke:'Durchführungskontrolle zeitnah, Wirksamkeitskontrolle regelmäßig – und das Ergebnis dokumentieren.'}
  ]},
  {t:'Faktoren der beruflichen Entwicklung',h:'6.1 Faktoren der beruflichen Entwicklung',pg:60,pdf:62,b:[
    {p:'Vorrangige Aufgabe des Meisters ist es, Mitarbeitende zu ihrer beruflichen Entwicklung zu beraten, zu fördern und zu unterstützen – auf Augenhöhe, durch Gelegenheiten und Rückmeldung. Informationen holt er intern (Personalabteilung, PE, Weiterbildung) und extern (Internet, IHK, Arbeitsagentur, Bildungsanbieter). Den Nutzen externer Angebote muss er bewerten können; hilfreich ist auch Wissen über Zukunftskompetenzen.'},
    {svg:{w:520,h:170,body:'<g class="sk-t" text-anchor="middle"><rect x="10" y="30" width="96" height="50" class="sk-body"/><text x="58" y="51" class="sk-t acc">Wachstum</text><text x="58" y="69">bis ca. 14</text><rect x="111" y="30" width="96" height="50" class="sk-body"/><text x="159" y="51" class="sk-t acc">Exploration</text><text x="159" y="69">ca. 15–24</text><rect x="212" y="30" width="96" height="50" class="sk-body"/><text x="260" y="51" class="sk-t acc">Etablierung</text><text x="260" y="69">ca. 25–44</text><rect x="313" y="30" width="96" height="50" class="sk-body"/><text x="361" y="51" class="sk-t acc">Erhaltung</text><text x="361" y="69">ca. 45–64</text><rect x="414" y="30" width="96" height="50" class="sk-body"/><text x="462" y="51" class="sk-t acc">Rückzug</text><text x="462" y="69">ab ca. 65</text><path d="M10,105 H505" class="sk-l" marker-end="url(#ar)"/><text x="260" y="125">Lebensalter</text><text x="260" y="155" class="sk-t acc">Heute: auch mit 50+ noch Karriereschritte</text></g>',cap:'Laufbahnstadien nach Donald E. Super'}},
    {tab:[['Laufbahnstadium (Super)','Kennzeichen'],['Wachstum','allgemeine körperliche und seelische Entwicklung'],['Exploration','verschiedene berufliche Tätigkeiten ausprobieren'],['Etablierung','berufliche Festlegung, Streben nach Dauerstellung'],['Erhaltung','Position halten, bis etwa 65 Jahre'],['Rückzug','Austritt aus dem Berufsleben']]},
    {ul:['Mit Supers Lebensrollen (Kind, Lernender, Freizeitrolle, Bürger, Erwerbstätiger, Partner, ggf. Elternteil) wird erklärbar, warum Karriere je nach Lebensphase mehr oder weniger zählt.','In der Etablierungsphase (Familiengründung, stabiles Umfeld) ist das Interesse an Karriereschritten mit Umzug oder vielen Überstunden oft begrenzt.','Früher waren Karriereschritte mit 40 meist abgeschlossen; heute sind 50-Jährige oft gesünder und mobiler und haben wieder Karriereinteresse (Kinder aus dem Haus).','Weitere Einflüsse: regionale und internationale Wirtschaftslage, Internationalisierung und Standortwechsel, Lebenssituation (z. B. pflegebedürftige Eltern), kürzere Halbwertszeit des Wissens.','Unternehmensseite: Prozesse, Verfahren, Technologien und Werkstoffe ändern sich, Kunden wollen individuellere Produkte → lebenslanges Lernen sichert die Beschäftigungsfähigkeit.','Informationen zu Entwicklungsmöglichkeiten liegen zunehmend nicht mehr zentral vor; Mitarbeitende und Vorgesetzte müssen interne und externe Quellen nutzen.']},
    {bsp:{t:'Beispiel: Entwicklung passend zur Lebensphase',b:['Mitarbeiter A, 29, junge Familie: wünscht keine Montageeinsätze im Ausland → Entwicklung am Standort, z. B. Qualifizierung zum Einrichter, Kurse in der Arbeitszeit.','Mitarbeiterin B, 52, Kinder erwachsen: möchte noch einmal Verantwortung → Ausbildung zur Ausbilderin (AEVO) und Übernahme der Azubi-Betreuung.','Mitarbeiter C, 61: Wissen sichern → Pate für zwei jüngere Kollegen, Dokumentation von Sonderverfahren, schrittweiser Übergang.','Meister informiert sich über IHK-Lehrgänge, Förderung (Aufstiegs-BAföG) und interne Angebote der Personalabteilung.']}},
    {merke:'Entwicklungswünsche hängen von der Lebensphase ab – im Gespräch erfragen statt unterstellen.'}
  ]},
  {t:'Maßnahmen der Mitarbeiterentwicklung und Coaching',h:'6.2 Maßnahmen der Mitarbeiterentwicklung',pg:61,pdf:63,abb:[['Abb. 6.1 Unterstützung der Mitarbeitenden bei der Umsetzung von Erlerntem',62]],b:[
    {p:'Ob Anpassungsfortbildung, Aufstiegsqualifizierung, Trainee oder erfahrene Fachkraft: Entwicklung muss geplant und systematisch erfolgen. Das regelmäßige Mitarbeitergespräch ist ein guter Anlass, über Veränderungen und nötige Kompetenzen zu sprechen. Interne und externe Weiterbildung sind ebenso wichtig wie arbeitsplatzbegleitende Maßnahmen; Unterstützung bei der Auswahl geben PE-Abteilung, IHK und externe Berater.'},
    {ul:['Direkte Vorgesetzte informieren, welche Kompetenzen heute und künftig gebraucht werden, und beraten im Fördergespräch, welche Qualifizierungen und Aufgaben sinnvoll sind.','Je nach Bedarf, Interesse und Bereitschaft konkrete Förderung: Seminare oder Lernmaterial finanzieren, zeitliche Freistellung.','Zentrale Bedeutung hat die kontinuierliche persönliche Förderung: Genauigkeit verbessern, Fehlerfreiheit fördern, zu mehr Selbstständigkeit anleiten.','Planung allein reicht nicht: Der größte Effekt für die Umsetzung des Lernens (rund 80 %) entsteht durch die Unterstützung der Führungskraft.','Trainer vermitteln Wissen, führen Übungen durch und ermutigen; die Umsetzung beeinflusst vor allem die Führungskraft: Gelegenheit zur Anwendung, Rahmenbedingungen, regelmäßige Rückmeldungen.','Vor der Maßnahme Ziel der Lernaktivität besprechen, bei Seminaren den Transferplan, danach zeitnah kurze Rückmeldungen.','Personalinformationssysteme und digitale Personalakten liefern ort- und zeitunabhängig Daten als Ausgangspunkt für Entwicklungsmaßnahmen.']},
    {tab:[['Begriff','Abgrenzung'],['Coaching (nach Rauen)','zeitlich begrenzter, personenzentrierter Beratungs- und Betreuungsprozess, beruflich und privat; individuelle Prozessberatung, auch präventiv – keine Ratschläge'],['„Coaching der Mitarbeitenden“ durch die Führungskraft','eigentlich Begleitung des Lern- und Entwicklungsprozesses: konkrete Beratung und Unterstützung'],['situative Qualifizierung durch die Führungskraft','z. B. bei Arbeitssicherheit oder Qualität sehr sinnvoll – ebenfalls kein Coaching im engen Sinn']]},
    {ul:['Wer disziplinarische Macht hat (Entgelt, Aufgaben, Beurteilung), hat meist nicht die Vertrauensbeziehung, die Coaching braucht.','Die Führungskraft kann aber ein Coaching veranlassen, wenn Reflexionsbedarf besteht: z. B. Nachwuchskraft scheut Abmahnungen oder Kündigungen und ist in Konflikten zu nachgiebig; Mitarbeiterin will sich entwickeln, kennt aber die Richtung nicht.','Erst interne Ansprechpartner (zeigen, was möglich ist), spezielle Entwicklungsberatung mit neigungsdiagnostischen Instrumenten eher durch Externe.']},
    {bsp:{t:'Beispiel: Neue Gruppenleiterin unterstützen',b:['Lage: Frau S. führt seit 3 Monaten die Gruppe Endmontage; Konflikte mit einem langjährigen Kollegen vermeidet sie.','Meister als Lernbegleiter: Wöchentliches 20-min-Gespräch, gemeinsame Vorbereitung eines Klärungsgesprächs, danach Rückmeldung.','Coaching: Auf Wunsch von Frau S. werden 4 Sitzungen bei einem externen Coach finanziert (Thema: eigene Rolle, Umgang mit Widerstand) – Inhalte bleiben vertraulich.','Förderung: Seminar „Führen ohne Vorgesetztenerfahrung“, Freistellung 2 Tage.','Nach 6 Monaten: Statusgespräch, Stellvertretung des Meisters im Urlaub als nächste Stufe.']}},
    {falle:'Der disziplinarische Vorgesetzte ist kein Coach im engen Sinn – er beurteilt und entscheidet. In der Prüfung sauber abgrenzen: Er begleitet, berät und fördert; Coaching übernehmen meist Externe.'}
  ]},
  {t:'Feedback und Rückmeldung',h:'6.2 Maßnahmen der Mitarbeiterentwicklung',pg:62,pdf:64,b:[
    {p:'Rückmeldungen können als Angriff erlebt werden. Feedback gibt Orientierung, wie Verhalten erlebt wird und ankommt. Kommt es von der disziplinarischen Führungskraft, müssen die Regeln besonders sorgfältig beachtet werden.'},
    {tab:[['Feedback','Rückmeldung'],['wird angeboten, nicht aufgedrängt („Möchten Sie hören, wie ich das erlebt habe?“)','wird gegeben, wenn eine zeitnahe Änderung nötig sein kann'],['enthält kein Urteil, sondern Beobachtung und Wirkung','bezieht sich auf übertragene Aufgabe oder neues Aufgabengebiet'],['muss annehmbar sein','in der Praxis viel häufiger gebraucht'],['konkret und kurz (Faustregel: unter 40 Wörtern)','nach Verhaltenspsychologie wichtig für nachhaltige Umsetzung']]},
    {svg:{w:520,h:260,body:'<g class="sk-t" text-anchor="middle"><polygon points="260,12 350,50 260,88 170,50" class="sk-body"/><text x="260" y="55">Umsetzung gelungen?</text><path d="M170,50 H130 V108" class="sk-l" marker-end="url(#ar)"/><path d="M350,50 H390 V108" class="sk-l" marker-end="url(#ar)"/><text x="150" y="42">ja</text><text x="372" y="42">nein</text><rect x="10" y="110" width="240" height="140" class="sk-body"/><text x="130" y="132" class="sk-t acc">positiv rückmelden</text><text x="130" y="160">sofort</text><text x="130" y="182">konkret sagen, was gut war</text><text x="130" y="204">Freude zeigen + begründen</text><text x="130" y="226">zum Weitermachen ermutigen</text><rect x="270" y="110" width="240" height="140" class="sk-body"/><text x="390" y="132" class="sk-t acc">korrigierend rückmelden</text><text x="390" y="160">sofort, Beobachtung nennen</text><text x="390" y="182">Erwartung klar machen</text><text x="390" y="204">Korrektur ermöglichen</text><text x="390" y="226">abschließen, ermutigen</text></g>',cap:'Regeln für Rückmeldungen nach der Umsetzung'}},
    {ul:['Gute Umsetzung: Mitarbeitende beim Gelingen „erwischen“; vorher ankündigen, dass es vermehrt Rückmeldungen geben wird; sofort sagen, was beobachtet wurde und gefiel; Freude ausdrücken und begründen; zum Weitermachen ermutigen.','Verbesserungsfähige Umsetzung: sofort; konkret beschreiben, was beobachtet wurde; eigene Vorstellung der Leistung zeigen und, wenn möglich, Gelegenheit zur Korrektur geben; ggf. sagen, dass man mit der übrigen Leistung zufrieden ist; deutlich machen, dass die Sache erledigt ist, und ermutigen statt ermahnen.','Neben Feedback und Rückmeldung: Unterstützung beim Erlernen neuer Tätigkeiten durch persönliche Einweisung oder Schulung.']},
    {bsp:{t:'Beispiel: Zwei Rückmeldungen am selben Tag',b:['Positiv: „Ich habe gesehen, dass Sie vor dem Anfahren der Presse das Werkzeug mit der neuen Checkliste geprüft haben. Das freut mich, weil wir damit Werkzeugbrüche vermeiden. Bitte machen Sie das so weiter.“ (unter 40 Wörtern)','Korrigierend: „Beim Rüsten eben lag der Schutzzaun offen, während die Maschine im Tippbetrieb lief. Ich erwarte, dass das Tor geschlossen ist – zeigen Sie mir bitte, wie Sie es beim nächsten Rüsten machen. Sonst bin ich mit Ihrer Arbeit sehr zufrieden.“','Danach: Sache ist erledigt, beim nächsten Rüsten kurz dabeistehen und positiv rückmelden, wenn es klappt.']}},
    {merke:'Beschreiben statt bewerten, sofort statt später, konkret statt allgemein – und gutes Verhalten genauso zurückmelden wie Fehler.'}
  ]}
 ]};
